window.ARTICLES=[{"id":1,"cat":"Thời sự","emoji":"🎗️","title":"TP.HCM chuẩn bị tiễn đưa 731 liệt sĩ về nơi an nghỉ mới","sapo":"Từng nghi thức được tổng duyệt, từng khâu tổ chức được rà soát, chuẩn bị tiễn đưa 731 liệt sĩ quy tập tại công viên Lê Thị Riêng (TP.HCM) về nơi an nghỉ ngày 14.10.","body":[{"t":"Sáng 12.10, tại công viên Lê Thị Riêng (P.Hòa Hưng, TP.HCM), những tiểu quách đựng hài cốt liệt sĩ được phủ Quốc kỳ, đặt trang trọng trong quách kính. Các lực lượng thực hành đội hình, nghi thức trong buổi tổng duyệt lễ viếng, truy điệu và an táng do Ban Chỉ đạo về tìm kiếm, quy tập và xác định danh tính hài cốt liệt sĩ TP.HCM tổ chức.","k":"p"},{"t":"Tổng duyệt lễ viếng, lễ truy điệu và lễ an táng hài cốt liệt sĩ tại công viên Lê Thị Riêng ngày 12.10 (Ảnh: NGỌC DƯƠNG)","k":"cap"},{"t":"Sau hơn 3 tháng tìm kiếm, công tác chuẩn bị tiễn đưa các liệt sĩ đang được hoàn thiện. Theo kế hoạch, 731 hài cốt liệt sĩ sẽ được an táng tại Nghĩa trang Liệt sĩ TP.HCM (P.Long Bình), gồm 698 hài cốt riêng lẻ và 33 hài cốt an táng chung trong một phần mộ tập thể.","k":"p"},{"t":"Chu đáo từng nghi thức","k":"h"},{"t":"Tại công viên Lê Thị Riêng, các lực lượng lần lượt thực hành nghi thức dâng hoa, dâng hương, lễ viếng và lễ truy điệu. Đội hình di chuyển quách hài cốt liệt sĩ được tổ chức, phối hợp đưa quách lên xe, chuẩn bị hành trình từ nơi quy tập đến nghĩa trang","k":"p"},{"t":"Di chuyển các quách lên xe để đưa các hài cốt liệt sĩ về Nghĩa trang Liệt sĩ TP.HCM (Ảnh: NGỌC DƯƠNG)","k":"cap"},{"t":"Bộ Tư lệnh TP.HCM bố trí khoảng 300 cán bộ, chiến sĩ phục vụ lễ viếng, truy điệu và an táng. Lực lượng Công an TP.HCM đảm nhiệm các nghi thức tiêu binh, đội danh dự và khiêng quách hài cốt liệt sĩ.","k":"p"},{"t":"Khoảng 8 giờ 30, đoàn xe tham gia tổng duyệt di chuyển đến Nghĩa trang Liệt sĩ TP.HCM. Tại đây, các lực lượng tiếp tục thực hành đón đoàn xe, đưa quách vào khu vực hành lễ, di chuyển đến vị trí an táng. Những bước phủ Quốc kỳ, hạ huyệt, mặc niệm, dâng hương và dâng những nắm đất đầu tiên xuống phần mộ được thực hiện theo kịch bản tổng duyệt.","k":"p"},{"t":"Cùng với nghi lễ, ban tổ chức kiểm tra nhân sự, phương tiện, công tác bảo đảm an ninh, trật tự và an toàn. Kết thúc phần tổng duyệt tại nghĩa trang, các lực lượng họp rút kinh nghiệm, tiếp tục hoàn thiện công tác chuẩn bị cho ngày tổ chức chính thức.","k":"p"},{"t":"Đại tá Nguyễn Đình Chuẩn, Phó chính ủy Bộ Tư lệnh TP.HCM, cho biết những ngày qua, các lực lượng tập trung xây dựng, luyện tập đội hình phục vụ nghi lễ. Buổi tổng duyệt giúp kiểm tra sự phối hợp, thống nhất cách thực hiện. Cán bộ, chiến sĩ tham gia với tác phong nghiêm túc, thái độ thành kính. Theo đại tá Chuẩn, đây là nhiệm vụ đặc biệt quan trọng, thể hiện tình cảm, trách nhiệm đối với những người đã chiến đấu, hy sinh vì Tổ quốc. Các lực lượng tiếp tục hoàn thiện từng nội dung, bảo đảm nghi thức trang trọng, đúng quy định và an toàn.","k":"p"},{"t":"Buổi lễ dự kiến có khoảng 1.000 đại biểu, cán bộ, chiến sĩ và các lực lượng tham gia. Thành phần gồm đại diện cơ quan, đơn vị, nhân chứng, Tổng lãnh sự quán Mỹ và Úc tại TP.HCM, các tổ chức chính trị - xã hội, chức sắc tôn giáo, dân tộc.","k":"p"},{"t":"Hành trình tiễn đưa dài khoảng 26 km","k":"h"},{"t":"Theo chương trình, lúc 19 giờ ngày 13.10, chương trình nghệ thuật đặc biệt Đêm tri ân diễn ra tại công viên Lê Thị Riêng.","k":"p"},{"t":"Sáng 14.10, lễ dâng hoa, dâng hương bắt đầu lúc 7 giờ 30 tại tượng đài cố Tổng Bí thư Trần Phú, Nhà bia liệt sĩ và các địa điểm trong công viên. Lễ viếng, truy điệu được tổ chức lúc 8 giờ. Sau các nghi thức viếng, đọc lời điếu và mặc niệm, hài cốt liệt sĩ được di chuyển về Nghĩa trang Liệt sĩ TP.HCM.","k":"p"},{"t":"Việc di chuyển chia thành 4 đợt, hoàn thành trong ngày 14.10; đợt đầu dự kiến xuất phát khoảng 8 giờ 45. Quãng đường dài khoảng 26 km, từ công viên qua đường Trường Sơn, Cách Mạng Tháng Tám, vòng xoay Dân Chủ, trở lại Cách Mạng Tháng Tám, rồi đi ra đường Điện Biên Phủ, cầu Sài Gòn, Võ Nguyên Giáp, xa lộ Hà Nội đến nghĩa trang.","k":"p"},{"t":"Đoàn xe phục vụ đưa hài cốt liệt sĩ về Nghĩa trang Liệt sĩ TP.HCM (Ảnh: NGỌC DƯƠNG)","k":"cap"},{"t":"Thời gian xuất phát và lộ trình có thể điều chỉnh theo điều hành của ban tổ chức, lực lượng chức năng để bảo đảm an toàn, trật tự giao thông.","k":"p"},{"t":"Ban Chỉ đạo đề nghị chính quyền, ban chỉ huy quân sự các địa phương có tuyến đường đoàn xe đi qua tuyên truyền, vận động người dân sinh sống hai bên đường đứng trên vỉa hè tiễn biệt. Người dân có thể cầm nhành hoa trắng, thành kính tiễn đưa các liệt sĩ; tuân thủ hướng dẫn của lực lượng chức năng, không ảnh hưởng đến an toàn giao thông.","k":"p"},{"t":"Lễ an táng dự kiến diễn ra lúc 10 giờ tại Nghĩa trang Liệt sĩ TP.HCM. Các lực lượng sẽ đón đoàn xe, đưa hài cốt đến vị trí an táng, thực hiện nghi thức hạ huyệt và dâng hương tưởng niệm.","k":"p"},{"t":"Chương trình được truyền hình trực tiếp trên HTV9, phát thanh trên VOH FM 99,9 MHz và các nền tảng số của Đài Phát thanh và truyền hình TP.HCM từ 8 - 10 giờ ngày 14.10.","k":"p"},{"t":"Nghiên cứu bảo tồn hố chôn tập thể liệt sĩ","k":"h"},{"t":"Tại Công văn 8215/UBND-VX ngày 7.9.2026, UBND TP.HCM giao Sở Văn hóa - Thể thao chủ trì nghiên cứu, đánh giá giá trị lịch sử - văn hóa khu vực hố chôn tập thể liệt sĩ tại công viên Lê Thị Riêng.","k":"p"},{"t":"Theo đó, Sở Văn hóa - Thể thao có trách nhiệm khảo sát hiện trạng, thu thập, xác minh và hệ thống hóa tư liệu lịch sử, tài liệu về quá trình tìm kiếm, quy tập để xác định giá trị, phạm vi nghiên cứu, bảo vệ địa điểm. Trên cơ sở kết quả nghiên cứu, Sở tham mưu các bước lập hồ sơ khoa học đề nghị xếp hạng di tích. Nếu có cơ sở đề nghị xếp hạng di tích quốc gia, phải thực hiện thủ tục xin ý kiến cơ quan quản lý di sản văn hóa ở Trung ương.","k":"p"},{"t":"UBND TP.HCM cũng yêu cầu nghiên cứu phương án khoanh vùng bảo vệ, xây dựng bia tưởng niệm, bia giới thiệu và các hạng mục phù hợp sau khi đánh giá giá trị, xác định phạm vi cần bảo vệ.","k":"p"},{"t":"Trong thời gian nghiên cứu, lập hồ sơ, UBND P.Hòa Hưng phối hợp đơn vị quản lý công viên giữ nguyên hiện trạng; không tự ý di dời, cải tạo, xây dựng hoặc thực hiện hoạt động có thể ảnh hưởng đến yếu tố lịch sử khi chưa có ý kiến của cơ quan có thẩm quyền.","k":"p"},{"t":"Bộ Tư lệnh TP.HCM cung cấp hồ sơ chiến đấu, sơ đồ, hình ảnh, lời kể nhân chứng và tư liệu quy tập. Sở Nội vụ phối hợp rà soát, xác minh thông tin liệt sĩ trong phạm vi hồ sơ quản lý.","k":"p"}]},{"id":2,"cat":"Thời sự","emoji":"🤝","title":"EU mong muốn tiếp tục đồng hành cùng Việt Nam trong giai đoạn phát triển mới","sapo":"Ngày 12.10, tại Trụ sở Chính phủ, Thủ tướng Lê Minh Hưng đã tiếp Đại sứ, Trưởng phái đoàn EU Julien Guerrier và các Đại sứ, Đại biện các nước thành viên EU tại Hà Nội.","body":[{"t":"Đánh giá quan hệ Việt Nam - EU, Thủ tướng Lê Minh Hưng nhấn mạnh sau 36 năm thiết lập quan hệ ngoại giao, quan hệ hai bên không ngừng phát triển mạnh mẽ, ngày càng đi vào chiều sâu và thực chất.","k":"p"},{"t":"Việt Nam là nước Đông Nam Á đầu tiên thiết lập Đối tác chiến lược toàn diện với EU; EU hiện là đối tác thương mại lớn thứ 4, thị trường xuất khẩu lớn thứ 3 và thị trường nhập khẩu lớn thứ 5 của Việt Nam. Thủ tướng khẳng định Việt Nam luôn coi trọng, dành ưu tiên cao cho quan hệ với EU và các nước thành viên, mong muốn cùng triển khai hiệu quả khuôn khổ quan hệ mới.","k":"p"},{"t":"Thủ tướng Lê Minh Hưng chụp ảnh lưu niệm cùng các đại biểu (Ảnh: BAOCHINHPHU)","k":"cap"},{"t":"Trong bối cảnh tình hình thế giới, khu vực diễn biến phức tạp, Thủ tướng Lê Minh Hưng đề nghị hai bên phát huy tiềm năng, lợi thế tăng cường phối hợp ứng phó các thách thức chung và mang lại lợi ích lâu dài; tiếp tục làm sâu sắc quan hệ Đối tác chiến lược toàn diện, tăng cường trao đổi đoàn, tiếp xúc các cấp, phối hợp chặt chẽ tại các diễn đàn đa phương, thúc đẩy hợp tác quốc phòng - an ninh, đồng thời mở rộng hợp tác trong các lĩnh vực mới, có ý nghĩa chiến lược như khoa học - công nghệ, đổi mới sáng tạo, nguyên liệu thô thiết yếu, hạ tầng chiến lược, chuyển đổi năng lượng, chuyển đổi số, chuyển đổi xanh,...","k":"p"},{"t":"Thủ tướng đề nghị hai bên tăng cường hợp tác trong phát triển năng lượng mới, công nghệ sản xuất hydrogen, amoniac xanh, công nghệ điện gió ngoài khơi, hiện đại hóa hạ tầng năng lượng; tăng cường hợp tác phát triển hạ tầng giao thông chiến lược, nhất là đường sắt tốc độ cao, đường sắt đô thị, cảng biển, hàng không; hỗ trợ về vốn, công nghệ, đào tạo nhân lực và khuyến khích doanh nghiệp châu Âu tham gia đầu tư.","k":"p"},{"t":"Thủ tướng nhấn mạnh sự cần thiết mở rộng hợp tác giáo dục - đào tạo, tăng cường trao đổi học thuật, đào tạo nguồn nhân lực chất lượng cao thông qua chương trình ERASMUS; đề nghị phía EU tiếp tục tạo thuận lợi cho cộng đồng người Việt Nam tại các nước EU hòa nhập vào xã hội sở tại, phát huy vai trò cầu nối giữa hai bên.","k":"p"},{"t":"Thủ tướng Chính phủ đề nghị các Đại sứ tiếp tục thúc đẩy triển khai hiệu quả EVFTA; sớm hoàn tất phê chuẩn EVIPA, tạo thuận lợi hơn nữa cho thương mại và đầu tư hai chiều; ủng hộ việc EC sớm gỡ \"Thẻ vàng\" IUU.","k":"p"},{"t":"Thủ tướng đánh giá cao việc EU ghi nhận những nỗ lực của Việt Nam trong hoàn thiện khuôn khổ pháp lý và tăng cường hợp tác về thuế và đã đưa Việt Nam ra khỏi Danh sách các vùng tài phán không hợp tác về thuế của EU. Với những vấn đề còn khác biệt, Thủ tướng đề nghị hai bên tiếp tục thông qua đối thoại và các cơ chế song phương hiện có, không để ảnh hưởng đến quan hệ hợp tác Đối tác chiến lược toàn diện.","k":"p"},{"t":"Thay mặt các Đại sứ, Đại biện các nước thành viên EU, Đại sứ, Trưởng phái đoàn EU tại Việt Nam Julien Guerrier cảm ơn Thủ tướng đã dành thời gian tiếp và trao đổi thực chất về các định hướng hợp tác.","k":"p"},{"t":"Đại sứ đánh giá quan hệ Việt Nam - EU ngày càng thực chất, tin cậy và năng động; nhấn mạnh Việt Nam có vai trò rất quan trọng trong bối cảnh thế giới diễn biến phức tạp hiện nay, vì vậy việc duy trì và tăng cường quan hệ hợp tác ổn định, tin cậy với Việt Nam có ý nghĩa đặc biệt quan trọng đối với EU.","k":"p"},{"t":"Đại sứ Julien Guerrier cho rằng hai bên đang có những cơ hội lớn để mở rộng hợp tác trên nhiều lĩnh vực. Với thế mạnh về công nghệ tiên tiến, chất lượng cao và những giải pháp phù hợp với nhu cầu phát triển của Việt Nam, các doanh nghiệp EU mong muốn tăng cường hợp tác, đầu tư, đặc biệt trong chuyển đổi xanh, chuỗi cung ứng, giao thông vận tải, hạ tầng chiến lược, nguyên liệu thô thiết yếu, khoa học - công nghệ, an ninh - quốc phòng và các lĩnh vực cùng quan tâm. Đại sứ khẳng định EU mong muốn tiếp tục đồng hành cùng Việt Nam trong giai đoạn phát triển mới.","k":"p"},{"t":"Hai bên nhất trí trước mắt cần chuẩn bị tốt cho hoạt động đối ngoại cấp cao và đẩy nhanh việc cụ thể hóa khuôn khổ Đối tác chiến lược toàn diện bằng những chương trình, dự án hợp tác thiết thực, có tầm nhìn dài hạn, tạo thêm động lực cho quan hệ Việt Nam - EU phát triển sâu rộng, hiệu quả trong thời gian tới.","k":"p"}]},{"id":3,"cat":"Thời sự","emoji":"✈️","title":"Chuyến thăm Lào, Campuchia của Thủ tướng Lê Minh Hưng đạt nhiều kết quả thực chất","sapo":"Chuyến công tác đối ngoại song phương đầu tiên của Thủ tướng Lê Minh Hưng tới Lào và Campuchia đã ghi dấu ấn đậm nét khi tháo gỡ căn bản nhiều điểm nghẽn dự án, thúc đẩy ký kết gần 40 văn kiện hợp tác và củng cố vững chắc trụ cột chiến lược với hai quốc gia láng giềng.","body":[{"t":"Trao đổi với báo chí về ý nghĩa và các kết quả quan trọng của chuyến thăm chính thức Lào và Campuchia của Thủ tướng Lê Minh Hưng, Bộ trưởng Bộ Ngoại giao Lê Hoài Trung khẳng định, chuyến thăm chính thức Lào và Campuchia của Thủ tướng Lê Minh Hưng đã thành công rất tốt đẹp, đạt nhiều kết quả quan trọng, thực chất, làm sâu sắc quan hệ hữu nghị truyền thống và tạo xung lực mới cho hợp tác toàn diện với hai nước láng giềng có vị trí quan trọng hàng đầu trong đường lối đối ngoại của Đảng, Nhà nước ta.","k":"p"},{"t":"Thủ tướng Lê Minh Hưng (Ảnh: CHINHPHU.VN)","k":"cap"},{"t":"\"Trước hết, chuyến thăm có ý nghĩa chính trị, đối ngoại rất quan trọng, vì đây là chuyến thăm chính thức Lào và Campuchia đầu tiên của Thủ tướng Lê Minh Hưng ở cương vị Thủ tướng Chính phủ và cũng là chuyến thăm song phương chính thức nước ngoài đầu tiên của Thủ tướng Lê Minh Hưng trên cương vị người đứng đầu Chính phủ\", ông Trung khẳng định,","k":"p"},{"t":"Đặc biệt, đối với Lào, đây là chuyến thăm đầu tiên của lãnh đạo chủ chốt Việt Nam và Thủ tướng ta cũng là lãnh đạo nước ngoài đầu tiên thăm Lào ngay sau khi nước bạn kiện toàn các vị trí lãnh đạo chủ chốt. Đảng, Nhà nước và Quốc hội Lào bầu ra Thủ tướng Chính phủ và Chủ tịch Quốc hội mới.","k":"p"},{"t":"Đối với Campuchia, chuyến thăm diễn ra đúng vào giai đoạn Campuchia đang tiếp tục thực hiện các kế hoạch quan trọng nhằm triển khai các chiến lược về phát triển kinh tế - xã hội và chuẩn bị các hoạt động đối ngoại quan trọng.","k":"p"},{"t":"Lãnh đạo cấp cao Lào và Campuchia đánh giá cao chuyến thăm thể hiện quan hệ đặc biệt, tình cảm hữu nghị truyền thống giữa hai nước cũng như quyết tâm của Đảng, Nhà nước và nhân dân Việt Nam trong việc cùng Lào, Campuchia đưa hợp tác vươn lên một tầm mức mới.","k":"p"},{"t":"Tạo thêm nguồn lực, động lực phát triển mới","k":"h"},{"t":"Qua chuyến thăm, Thủ tướng Lê Minh Hưng và lãnh đạo cấp cao Lào, Campuchia đã trao đổi về nhiều nội dung liên quan đến quan hệ hai Đảng, hai nước, các mặt hợp tác cũng như các vấn đề quốc tế và khu vực cùng quan tâm; qua đó tăng cường tin cậy chính trị, hiểu biết lẫn nhau và định hướng chính trị quan trọng cho quan hệ giữa Việt Nam với Lào và Campuchia, khẳng định tầm quan trọng đặc biệt của quan hệ hợp tác về quốc phòng - an ninh, trụ cột của quan hệ.","k":"p"},{"t":"Thứ hai, một ý nghĩa rất quan trọng nữa của chuyến thăm lần này là Thủ tướng Lê Minh Hưng đã cùng lãnh đạo Lào và Campuchia trao đổi, đánh giá tình hình triển khai hợp tác cụ thể trong các lĩnh vực; cùng các bộ, ngành giải quyết dứt điểm cơ bản những khó khăn của các dự án thời gian qua, tích cực triển khai đem lại kết quả thiết thực đối với các dự án hợp tác được Bộ Chính trị, hai Tổng Bí thư, Chủ tịch nước Việt Nam và Lào, cũng như Bộ Chính trị Đảng Cộng sản Việt Nam và Ban Thường vụ Đảng Nhân dân Campuchia, lãnh đạo Campuchia nhất trí; đồng thời, cũng mở ra các hướng, lĩnh vực và dự án hợp tác mới có tiềm năng, tạo thêm động lực, nguồn lực phát triển mới cho cả Việt Nam, Lào và Campuchia.","k":"p"},{"t":"Thứ ba, chuyến thăm lần này cũng triển khai tích cực đường lối đối ngoại Đại hội XIV của Đảng, thể hiện sự coi trọng và ưu tiên quan hệ láng giềng đối với Lào và Campuchia.","k":"p"},{"t":"Chuyến thăm cũng là bước chuẩn bị rất quan trọng cho các hoạt động đối ngoại cấp cao quan trọng giữa Việt Nam với Lào và Campuchia thời gian tới và đặc biệt để chuẩn bị cho các sự kiện rất quan trọng của Việt Nam với Lào và Campuchia trong năm 2027.","k":"p"},{"t":"Đây là những dấu mốc có ý nghĩa quan trọng, tạo thêm động lực để tiếp tục củng cố tin cậy chính trị, tăng cường gắn kết chiến lược và thúc đẩy quan hệ giữa Việt Nam với Lào và Campuchia phát triển lên tầm cao mới.","k":"p"},{"t":"\"Chỉ trong chưa đến 48 giờ, Thủ tướng Lê Minh Hưng và Đoàn đại biểu cấp cao Việt Nam đã có nhiều hoạt động quan trọng, phong phú, tiếp xúc với tất cả lãnh đạo cấp cao của Lào và Campuchia, tham dự và phát biểu tại các diễn đàn doanh nghiệp, xúc tiến đầu tư với sự tham dự đông đảo của doanh nghiệp Việt Nam, Lào và Campuchia tại hai nước, chứng kiến việc ký kết, trao gần 40 văn kiện, thỏa thuận giữa các cơ quan, địa phương, doanh nghiệp hai nước; gặp gỡ đại diện cộng đồng người Việt Nam ở nước ngoài và cán bộ đại sứ quán ta tại hai nước\", ông Trung chia sẻ.","k":"p"}]},{"id":4,"cat":"Thể thao","emoji":"⚽","title":"Chủ tịch FIFA Infantino có nguy cơ \"mất ghế\"","sapo":"Chủ tịch FIFA Gianni Infantino trở thành tâm điểm vụ bê bối mới, liên quan hàng triệu euro thiếu minh bạch, khiến uy tín cá nhân ông tiếp tục bị sụt giảm.","body":[{"t":"Chủ tịch FIFA Gianni Infantino tiếp tục vướng vào các bê bối tài chính - Ảnh: REUTERS","k":"cap"},{"t":"Báo The Times (Anh) cáo buộc Chủ tịch FIFA Gianni Infantino đã nhận hàng triệu euro không được kê khai công khai. Số tiền này nằm ngoài khoản lương cơ bản và các khoản thưởng được quy định dành cho vị trí Chủ tịch FIFA. Theo The Times, số tiền hàng triệu euro không công khai nói trên là để \"phục vụ lối sống xa hoa\" của chủ tịch FIFA tại Miami (Mỹ).","k":"p"},{"t":"Truyền thông châu Âu cho biết kể từ năm 2016, FIFA đã công bố hằng năm mức thù lao của Chủ tịch và Tổng thư ký của tổ chức này.","k":"p"},{"t":"Tuy nhiên, cuộc điều tra của The Times chỉ ra rằng ông Infantino có thể đã nhận thu nhập từ hai nguồn khác nhau.","k":"p"},{"t":"Nguồn thứ nhất là khoản lương, thưởng chính thức do FIFA chi trả và được ghi nhận đầy đủ trong báo cáo tài chính thường niên. Nguồn thứ hai là các khoản tiền không được công khai, do đơn vị phụ trách tổ chức World Cup tại Mỹ chuyển vào tài khoản của ông Infantino. Theo báo cáo thường niên của FIFA, trong năm 2024, Infantino nhận tổng cộng 4,274 triệu franc Thụy Sĩ.","k":"p"},{"t":"Tuy nhiên, một hồ sơ khai thuế do Công ty FWC2026 US Inc nộp lên Sở Thuế vụ Mỹ (IRS) cho thấy Chủ tịch FIFA còn được chi trả thêm 1,6 triệu euro trong cùng năm. Những khoản tiền này chưa từng được FIFA công bố.","k":"p"},{"t":"Trong số tiền nói trên, hơn 500.000 euro được ghi là \"khoản thù lao khác thuộc diện phải kê khai\". Khoản tiền này đã được sử dụng để trang trải chi phí thuê một biệt thự ven biển tại Sunset Islands - một trong những khu vực đắt đỏ và biệt lập bậc nhất Miami Beach, nổi tiếng với các khu dân cư siêu sang.","k":"p"},{"t":"Khi được The Times liên hệ để làm rõ, FIFA không xác nhận những thông tin trên. Tổ chức này cũng không đưa ra lời giải thích về các khoản thanh toán không được công khai dành cho ông Infantino.","k":"p"},{"t":"Bên cạnh đó, các nguồn tin được The Times tham khảo khẳng định ông Infantino có thể đã nhận những khoản tiền tương tự, thậm chí còn lớn hơn, trong các năm 2025 và 2026.","k":"p"},{"t":"Vụ bê bối mới này khiến uy tín của ông Infantino tiếp tục sụt giảm và ảnh hưởng nghiêm trọng đến việc ông tái cử Chủ tịch FIFA nhiệm kỳ tiếp theo. Cuộc bầu cử FIFA sẽ diễn ra vào tháng 3-2027.","k":"p"}]},{"id":5,"cat":"Thể thao","emoji":"🏆","title":"Việt Nam nhận thêm tin vui lớn trong kế hoạch World Cup","sapo":"Giới truyền thông phương Tây tin rằng kế hoạch mở rộng quy mô World Cup lên 64 đội nhiều khả năng sẽ thành hiện thực. Hơn nữa, châu Á nói chung và Việt Nam nói riêng có thể hưởng lợi lớn.","body":[{"t":"Ông Infantino và Chủ tịch Liên đoàn Bóng đá Việt Nam Trần Quốc Tuấn - Ảnh: FIFA","k":"cap"},{"t":"Thông tin về việc mở rộng quy mô World Cup lên 64 đội rất được người hâm mộ làng bóng đá chờ đợi, đặc biệt là fan ở những nền bóng đá đang tiến gần giấc mơ World Cup như Việt Nam.","k":"p"},{"t":"Kế hoạch dần thành hiện thực, Việt Nam tăng hy vọng","k":"h"},{"t":"Sau hơn một tháng \"im hơi lặng tiếng\" về kế hoạch này, truyền thông phương Tây mới đây đã đưa ra những đánh giá rất tích cực về dự án World Cup 64 đội. Đặc biệt, châu Á được đánh giá là châu lục hưởng lợi nhiều nhất.","k":"p"},{"t":"Trong bài bình luận đăng ngày 10-10, báo Financial Times của Anh viết: “World Cup 2030 nhiều khả năng sẽ tăng lên 64 đội, FIFA đang hoàn thiện những thủ tục cuối cùng”. Báo phân tích việc mở rộng giải giúp tăng nguồn thu và cơ hội tham dự cho các quốc gia nhỏ, qua đó củng cố sự ủng hộ dành cho Chủ tịch FIFA Gianni Infantino. Đây chắc chắn là đánh giá khách quan, dựa trên những nguồn tin của báo chí châu Âu - vốn luôn tỏ rõ lập trường chống đối ông Infantino.","k":"p"},{"t":"Đề xuất 64 đội ban đầu được Liên đoàn Bóng đá Nam Mỹ (CONMEBOL) thúc đẩy nhằm đánh dấu 100 năm World Cup vào năm 2030.","k":"p"},{"t":"FIFA sau đó đã lập một lịch trình cho dự án này, bao gồm việc lựa chọn các đơn vị nghiên cứu (chốt ngày 14-8) và nhận báo cáo (chốt ngày 11-9). Sau một tháng kể từ khi nhận các bản báo cáo, FIFA đang bắt đầu xúc tiến kế hoạch mở rộng World Cup như dự đoán của truyền thông phương Tây.World Cup mở rộng quy mô lên 64 đội, và châu Á (AFC) có thể trở thành Liên đoàn Bóng đá cấp lục địa hưởng lợi nhất trong dự án này.","k":"p"},{"t":"Châu Á hưởng lợi thế nào?","k":"h"},{"t":"Nhà báo Jesse Yomtov của USA Today (Mỹ) đưa ra dự báo số đội châu Á dự World Cup có thể tăng từ 8 suất trực tiếp trong thể thức 48 đội lên 12 suất trực tiếp trong thể thức 64 đội. Đó là chưa tính đến những suất dự vòng play-off liên lục địa.","k":"p"},{"t":"Báo La Gazzetta dello Sport của Ý cũng đưa ra con số 12 suất chính thức phân bổ cho châu Á trong bài phân tích của chuyên gia Fabio Licari. Theo trang báo uy tín này, FIFA sẽ cấp 19-20 suất chính thức cho châu Âu, 12-13 cho châu Phi, 12 cho châu Á, 8-9 cho Nam Mỹ, 7-8 cho Bắc Mỹ và 1-2 cho châu Đại Dương.","k":"p"},{"t":"Ông Infantino liên tục sang Đông Nam Á giao lưu, dự sự kiện - Ảnh: THAIRATH","k":"cap"},{"t":"Đài Sky Sports thận trọng hơn, chỉ dự đoán rằng châu Á có \"tối thiểu 10 suất chính thức\" với thể thức mới. Còn báo Osen của Hàn Quốc tin rằng châu Á sẽ có 11-12 suất chính thức.","k":"p"},{"t":"Dù là con số nào đi nữa, châu Á chắc chắn sẽ nhận thêm nhiều suất hơn khi World Cup mở rộng quy mô. Và đó chính là cơ hội lớn để Việt Nam hiện thức hóa giấc mơ góp mặt tại ngày hội bóng đá số một hành tinh.","k":"p"},{"t":"Có một cơ sở để tin rằng FIFA sẽ ưu ái châu Á trong kế hoạch World Cup 64 đội. Đó là \"lời hứa\" của Chủ tịch Gianni Infantino, người đang tích cực hoạt động ở châu Á thời gian qua.","k":"p"},{"t":"Chỉ trong khoảng 3 tháng gần đây, ông Infantino đã nhiều lần sang Việt Nam, Indonesia, Uzbekistan... để dự các sự kiện, giải đấu lớn. Báo The Guardian của Anh tin rằng chủ tịch FIFA cần có sự hậu thuẫn của châu Á để tái đắc cử vào tháng 3-2027.","k":"p"},{"t":"Và nếu ông Infantino giữ được ghế, kế hoạch mở rộng World Cup lên 64 đội chắc chắn sẽ được thông qua.","k":"p"}]},{"id":6,"cat":"Pháp luật","emoji":"⚖️","title":"Phạm Thoại đập tivi, Khá Bảnh đốt xe: Khi \"giang hồ mạng\" nổi loạn - Ranh giới giữa bày tỏ cảm xúc và vi phạm pháp luật","sapo":"Từ vụ TikToker Phạm Thoại đập tivi đến Khá Bảnh đốt xe máy rồi đăng lên mạng xã hội, câu hỏi đặt ra là chủ sở hữu có được tùy ý phá hủy tài sản của mình? Luật sư phân tích ranh giới giữa quyền định đoạt tài sản và những hành vi có thể bị xử phạt.","body":[{"t":"Đoạn video TikToker Phạm Thoại nổi giận, đập vỡ chiếc tivi màn hình lớn sau đêm chung kết Miss Grand International 2026 đang gây nhiều tranh luận trên mạng xã hội.","k":"p"},{"t":"Theo video được đăng tải trên mạng xã hội, sau khi đại diện Việt Nam Emoura Phạm giành danh hiệu á hậu 4 tại cuộc thi, Phạm Thoại đăng video ghi lại cảnh mình đập tivi. Nhiều người cho rằng hành động này phản cảm, lãng phí tài sản, trong khi một số ý kiến đặt nghi vấn về việc tạo nội dung gây sốc để thu hút tương tác.","k":"p"},{"t":"Câu chuyện cũng khiến nhiều người nhớ đến vụ Khá Bảnh từng đập phá, đốt xe máy rồi đăng video lên YouTube, gây xôn xao dư luận năm 2019.","k":"p"},{"t":"Từ hai vụ việc, một câu hỏi được đặt ra: Nếu tài sản thuộc sở hữu hợp pháp của mình, một người có quyền tự đập phá, tiêu hủy hay không? Và khi hình ảnh ấy được đưa lên mạng xã hội, thu hút đông đảo người xem, liệu có thể bị xử phạt?","k":"p"},{"t":"Phạm Thoại đập tivi của mình có vi phạm pháp luật?","k":"h"},{"t":"Trao đổi với Tuổi Trẻ, luật sư Nguyễn Đại Hải (Công ty Luật TNHH Fanci) cho rằng cần phân biệt giữa quyền định đoạt tài sản của chủ sở hữu với những hậu quả có thể phát sinh từ cách thực hiện quyền này.","k":"p"},{"t":"Theo Điều 158 Bộ luật Dân sự năm 2015, quyền sở hữu bao gồm quyền chiếm hữu, quyền sử dụng và quyền định đoạt tài sản. Trong đó Điều 192 và Điều 194 cho phép chủ sở hữu tiêu dùng, tiêu hủy hoặc thực hiện những hình thức định đoạt khác đối với tài sản của mình theo quy định pháp luật.","k":"p"},{"t":"Nói một cách dễ hiểu, nếu một người bỏ tiền mua chiếc tivi, xác lập quyền sở hữu hợp pháp thì họ có quyền quyết định tiếp tục sử dụng, bán, cho tặng hoặc tiêu hủy chiếc tivi đó.","k":"p"},{"t":"\"Vì vậy việc tự đập vỡ một chiếc tivi thuộc sở hữu riêng không mặc nhiên bị coi là hành vi vi phạm pháp luật\", ông Hải nhìn nhận.","k":"p"},{"t":"Tuy nhiên luật sư Hải lưu ý quyền định đoạt tài sản không phải là quyền tuyệt đối. Chủ sở hữu không được thực hiện quyền của mình trái pháp luật, gây thiệt hại hoặc xâm phạm lợi ích công cộng, quyền và lợi ích hợp pháp của người khác.","k":"p"},{"t":"\"Chẳng hạn, một người tự đập bỏ đồ đạc trong nhà, không gây nguy hiểm và không ảnh hưởng đến ai khác sẽ khác với trường hợp đập phá giữa nơi đông người, gây mất trật tự hoặc làm hư hỏng tài sản xung quanh.","k":"p"},{"t":"Tùy tính chất, mức độ và hậu quả, người thực hiện có thể bị xử phạt hành chính, thậm chí bị truy cứu trách nhiệm hình sự nếu đủ yếu tố cấu thành tội phạm\", luật sư Hải phân tích.","k":"p"},{"t":"Luật sư Nguyễn Đại Hải - Ảnh: NVCC","k":"cap","img":"6-2"},{"t":"Cùng quan điểm, luật sư Vũ Tuấn Linh (Công ty Luật TNHH Đông Hà Nội) cho rằng pháp luật không đặt ra chế tài chỉ vì một người tự phá hủy tài sản thuộc sở hữu hợp pháp của mình.","k":"p"},{"t":"Theo ông Linh, quy định pháp luật đặt ra những giới hạn đối với việc thực hiện quyền sở hữu, bảo đảm không trái pháp luật, không xâm phạm lợi ích công cộng và quyền, lợi ích hợp pháp của người khác.","k":"p"},{"t":"Luật sư Linh phân tích thêm nếu việc đập phá tài sản gây mất trật tự công cộng, người thực hiện có thể bị xử phạt hành chính, thậm chí bị truy cứu trách nhiệm hình sự theo Điều 318 Bộ luật Hình sự nếu đủ yếu tố cấu thành tội phạm.","k":"p"},{"t":"Trường hợp gây thiệt hại đến sức khỏe, tài sản của người khác, người thực hiện còn có thể phải bồi thường theo Điều 584 Bộ luật Dân sự.","k":"p"},{"t":"\"Sự lãng phí hoặc phản cảm không tự tạo ra căn cứ áp dụng chế tài\", luật sư Linh nhấn mạnh.","k":"p"},{"t":"Trở lại vụ Phạm Thoại, cả hai luật sư đều cho rằng chưa thể chỉ dựa vào hình ảnh đập tivi để kết luận TikToker này vi phạm pháp luật.","k":"p"},{"t":"Luật sư Hải phân tích nếu chiếc tivi thực sự thuộc sở hữu riêng hợp pháp của Phạm Thoại, hành vi diễn ra trong không gian riêng, không gây nguy hiểm, không làm hư hỏng tài sản của người khác và không vi phạm quy định pháp luật khác thì về cơ bản đây là việc thực hiện quyền định đoạt tài sản.","k":"p"},{"t":"Luật sư Linh cũng cho rằng với những giả định trên, không có căn cứ áp dụng chế tài chỉ vì Phạm Thoại đập tivi để thể hiện cảm xúc thất vọng trước kết quả một cuộc thi sắc đẹp.","k":"p"},{"t":"Tuy nhiên hai luật sư lưu ý cần xem xét riêng một tình tiết khác: Hành vi đập phá không chỉ diễn ra trước những người có mặt mà còn được ghi hình, đăng tải công khai lên mạng xã hội.","k":"p"},{"t":"Đăng video đập phá lên mạng, khi nào có thể bị phạt?","k":"h"},{"t":"Theo luật sư Nguyễn Đại Hải, quyền tự định đoạt tài sản và trách nhiệm khi sử dụng mạng xã hội là hai vấn đề pháp lý khác nhau.","k":"p"},{"t":"Một người có thể được quyền tiêu hủy tài sản của mình, nhưng khi quay video rồi đăng tải công khai, nội dung đó vẫn phải tuân thủ các quy định về cung cấp, chia sẻ thông tin trên không gian mạng. Luật sư viện dẫn pháp luật quy định mức phạt 20-30 triệu đồng đối với một số hành vi chia sẻ nội dung vi phạm pháp luật trên mạng xã hội, trong đó có nội dung phá hoại thuần phong, mỹ tục, đạo đức xã hội. Tuy nhiên việc xử phạt phải căn cứ vào hành vi vi phạm cụ thể, không thể chỉ dựa vào việc video bị cho là phản cảm hoặc gây tranh cãi.","k":"p"},{"t":"Ở góc nhìn này, luật sư Vũ Tuấn Linh nhấn mạnh việc một video thu hút nhiều lượt xem, gây xôn xao dư luận không phải là căn cứ độc lập để xử phạt.","k":"p"},{"t":"Nếu video chỉ ghi lại việc chủ sở hữu đập tài sản của mình để bộc lộ cảm xúc, không chứa nội dung kích động, kêu gọi, xúi giục, cổ xúy bạo lực hoặc những nội dung bị pháp luật cấm thì không thể xử phạt chỉ vì video được đăng lên mạng.","k":"p"},{"t":"Ngược lại, khi nội dung đăng tải vượt qua ranh giới thể hiện cảm xúc để trở thành hành vi kích động, cổ xúy bạo lực hoặc xâm phạm quyền và lợi ích hợp pháp của người khác, trách nhiệm pháp lý có thể được đặt ra.","k":"p"},{"t":"Luật sư Linh dẫn Luật An ninh mạng năm 2025 có điều khoản quy định nghiêm cấm hành vi kích động, cổ xúy bạo lực...","k":"p"},{"t":"Theo ông, muốn xác định một video có vi phạm hay không phải xem xét toàn bộ nội dung, thông điệp, lời nói và những thông tin đi kèm. Không thể đồng nhất mọi hình ảnh đập đồ vật với hành vi cổ xúy, kích động bạo lực.","k":"p"},{"t":"\"Việc phê bình một cách ứng xử và kết luận một hành vi vi phạm pháp luật là hai đánh giá có căn cứ khác nhau\", luật sư Linh nêu quan điểm.","k":"p"},{"t":"Điều này cũng có nghĩa việc một người nổi tiếng đăng video đập phá tài sản và bị dư luận phản ứng gay gắt chưa đủ để khẳng định người đó phải chịu trách nhiệm pháp lý.","k":"p"},{"t":"Khá Bảnh đốt xe, Phạm Thoại đập tivi: Khác nhau ở đâu?","k":"h"},{"k":"cap","t":"Khá Bảnh trong vụ đốt xe máy năm 2019","img":"6-1"},{"t":"Tháng 3-2019, Ngô Bá Khá, thường được biết đến với biệt danh Khá Bảnh, từng gây xôn xao khi đăng video ghi lại cảnh đập phá rồi đốt một chiếc xe máy Honda PCX.","k":"p"},{"t":"Trong video, Khá Bảnh đưa ra lý do chiếc xe tốn xăng và chuyển sang sử dụng xe điện. Sau khi sự việc lan truyền, Công an tỉnh Bắc Ninh đã vào cuộc xác minh, còn Khá Bảnh xóa video và lên tiếng xin lỗi.","k":"p"},{"t":"Vụ việc khi đó làm dấy lên tranh luận về việc một người có được tự đốt xe máy của mình hay không, đặc biệt khi hành vi được quay lại rồi đăng tải lên mạng xã hội.","k":"p"},{"t":"Đặt vụ Khá Bảnh bên cạnh trường hợp Phạm Thoại, luật sư Nguyễn Đại Hải cho rằng điểm chung là những hành vi đập phá tài sản được ghi hình, công khai trên mạng và gây phản ứng trái chiều.","k":"p"},{"t":"Tuy nhiên trách nhiệm pháp lý không thể được xác định chỉ dựa vào sự tương đồng đó.","k":"p"},{"t":"Theo luật sư, yếu tố đầu tiên cần làm rõ là tài sản bị phá hủy thuộc sở hữu của ai. Tiếp đến là địa điểm, cách thức thực hiện, những ảnh hưởng đối với cộng đồng và nội dung video được đăng tải.","k":"p"},{"t":"\"Nếu việc đập phá diễn ra tại nhà riêng, không gây nguy hiểm, không ảnh hưởng đến người khác thì tính chất sẽ khác với hành vi đập phá tại nơi công cộng gây mất trật tự.","k":"p"},{"t":"Đặc biệt, việc sử dụng lửa để đốt xe có thể làm phát sinh những nguy cơ về an toàn cháy, nổ mà hành vi đập tivi không mặc nhiên có\", ông Hải đánh giá.","k":"p"},{"t":"Luật sư Vũ Tuấn Linh phân tích thêm vụ Khá Bảnh có những tình tiết riêng cần được xem xét.","k":"p"},{"t":"Khá Bảnh cùng những người khác đập rồi dùng xăng đốt xe tại một bãi đất trống trong khu vực trường lái xe. Việc chuẩn bị và sử dụng xăng, lửa đặt ra vấn đề về an toàn cháy và môi trường.","k":"p"},{"t":"Trong khi đó trường hợp Phạm Thoại được biết đến qua video đập tivi trong một căn phòng. Chưa có căn cứ để khẳng định hành vi gây mất trật tự hoặc thiệt hại cho người khác.","k":"p"},{"t":"Từ hai vụ việc, các luật sư cho rằng quyền sở hữu tài sản được pháp luật bảo vệ, nhưng việc thực hiện quyền đó vẫn phải có giới hạn, nhất là khi có thể ảnh hưởng đến an toàn, trật tự công cộng hoặc quyền lợi của người khác.","k":"p"}]},{"id":7,"cat":"Công nghệ","emoji":"🛵","title":"Xe máy điện \u0027ăn nắng thay cơm\u0027, đi làm mỗi ngày có thể không cần cắm sạc","sapo":"Mẫu xe máy điện Lightfoot gây chú ý với hai tấm pin mặt trời tích hợp ở thân xe, có thể bổ sung năng lượng đủ đi 29km mỗi ngày.","body":[{"t":"Hai bên thân xe được bao phủ bởi những tấm pin mặt trời lớn, vừa tạo nên kiểu dáng khác biệt, vừa đóng vai trò cung cấp năng lượng - Ảnh: Otherlab","k":"cap"},{"t":"Một chiếc xe máy điện có thể tự sạc khi đỗ ngoài trời, đủ chỗ cho hai người và có khoang chứa đồ lớn để đi siêu thị. Đó là ý tưởng đằng sau Lightfoot, mẫu xe máy điện vừa được Công ty nghiên cứu và phát triển Otherlab tại San Francisco (Mỹ) đưa ra thị trường.","k":"p"},{"t":"Khác với xu hướng tăng công suất, tốc độ và kích thước của nhiều xe điện hiện nay, Lightfoot được thiết kế cho những chuyến đi ngắn trong đô thị. Xe chỉ có tốc độ tối đa dưới 32km/h, đổi lại là khả năng tận dụng năng lượng mặt trời để giảm số lần cắm sạc.","k":"p"},{"t":"Đỗ ngoài trời có thể tự sạc điện","k":"h"},{"t":"Điểm gây chú ý nhất trên Lightfoot là hai tấm pin mặt trời kích thước lớn gắn dọc hai bên thân xe. Mỗi tấm có công suất 120W, đưa tổng công suất hệ thống lên 240W.","k":"p"},{"t":"Theo Otherlab, trong điều kiện nắng tốt, mỗi giờ đỗ ngoài trời có thể giúp xe tích lũy lượng điện đủ di chuyển thêm khoảng 5 - 6km. Nếu tiếp xúc với ánh nắng thuận lợi trong cả ngày, phạm vi hoạt động có thể tăng thêm tối đa 29km.","k":"p"},{"t":"Lightfoot sử dụng bộ pin dung lượng 1,56kWh, cho quãng đường di chuyển tối đa 60km sau mỗi lần sạc đầy.","k":"p"},{"t":"Với một người đi làm cách nhà khoảng 8km, tổng quãng đường cả đi lẫn về chỉ khoảng 16km mỗi ngày. Về lý thuyết, nếu xe được đỗ dưới nắng trong suốt thời gian làm việc, lượng điện thu được có thể đủ bù lại năng lượng tiêu thụ.","k":"p"},{"t":"Nếu chỉ dùng đi làm hằng ngày, sạc bằng năng lượng mặt trời là đủ dùng - Ảnh: Otherlab","k":"cap"},{"t":"Tuy nhiên, khả năng này còn phụ thuộc vào thời tiết, cường độ ánh nắng và vị trí đỗ xe. Những ngày trời nhiều mây hoặc xe để trong nhà, hiệu quả sạc bằng năng lượng mặt trời sẽ giảm đáng kể.","k":"p"},{"t":"Nhà sản xuất vẫn trang bị bộ sạc công suất 230W, cho phép cắm vào ổ điện dân dụng. Thời gian sạc đầy được công bố khoảng 4 giờ.","k":"p"},{"t":"Như vậy, Lightfoot không hoàn toàn chỉ cần dựa vào ánh nắng, nhưng có thể giảm đáng kể nhu cầu cắm sạc đối với những người thường xuyên di chuyển quãng đường ngắn. Giá gần 120 triệu đồng","k":"p"},{"t":"Sau gần hai năm kể từ khi nguyên mẫu được giới thiệu, Lightfoot đã bước vào giai đoạn mở bán và giao xe.","k":"p"},{"t":"Việc chi gần 120 triệu đồng cho một phương tiện tốc độ thấp có thể khiến nhiều người chùn bước - Ảnh: Otherlab","k":"cap"},{"t":"100 chiếc đầu tiên thuộc phiên bản Launch Edition được niêm yết ở mức 4.495 USD, tương đương khoảng 116,5 triệu đồng, bao gồm chi phí giao hàng.","k":"p"},{"t":"Mức giá này khá cao đối với một chiếc xe máy điện có tốc độ tối đa chưa tới 32km/h. Trên thị trường, nhiều mẫu xe máy điện và xe đạp điện có khả năng vận hành tương đương, thậm chí nhanh hơn, nhưng giá thấp hơn đáng kể.","k":"p"},{"t":"Ngoài ra, thiết kế với hai tấm pin mặt trời lớn ở hai bên thân cũng đặt ra câu hỏi về khả năng ổn định khi gặp gió tạt mạnh.","k":"p"},{"t":"Do đó sẽ cần thêm thời gian để có thể khẳng định được liệu khả năng ít phải cắm sạc có đủ thuyết phục người mua bỏ thêm tiền hay không. Bài này chắc chắn phải có ít nhất là 2 hình trên đó nhe","k":"p"}]},{"id":8,"cat":"Thế giới","emoji":"🏛️","title":"Nhà Trắng sắp có tân thư ký báo chí: Từng sống tại Bắc Kinh, biết tiếng Trung","sapo":"Tân Thư ký báo chí Nhà Trắng Katie Zacharia từng có 2 năm làm việc tại thủ đô Bắc Kinh và có thể giao tiếp bằng tiếng Trung Quốc.","body":[{"t":"Tân thư ký báo chí Nhà Trắng Katie Zacharia - Ảnh: CNN","k":"cap"},{"t":"Tổng thống Mỹ Donald Trump đã chính thức bổ nhiệm bà Katie Zacharia (42 tuổi), nhà bình luận chính trị bảo thủ và chuyên gia truyền thông, giữ vị trí Thư ký báo chí Nhà Trắng, thay thế người tiền nhiệm Karoline Leavitt.","k":"p"},{"t":"\"Tôi vui mừng thông báo Katie Zacharia sẽ chính thức bắt đầu nhiệm kỳ thư ký báo chí vào ngày mai, dịp lễ Columbus Day và sẽ tổ chức buổi họp báo ra mắt vào lúc 9h30 sáng 13-10 tại phòng họp báo của Nhà Trắng\", ông Trump thông báo ngày 11-10.","k":"p"},{"t":"Nhà lãnh đạo Mỹ cũng đánh giá cao sự trung thành và những đóng góp của bà Zacharia trong các chiến dịch tranh cử trước đây tại các bang chiến địa.","k":"p"},{"t":"\"Katie Zacharia từng tham gia các chiến dịch tranh cử của tôi, hỗ trợ vận động tại những bang chiến địa then chốt, nơi chúng tôi giành chiến thắng cả 7/7 bang\", ông Trump ca ngợi.","k":"p"},{"t":"Từ Malibu đến Bắc Kinh","k":"h"},{"t":"Bà Zacharia từng theo học luật tại Trường Luật Caruso thuộc Đại học Pepperdine ở Malibu, bang California.","k":"p"},{"t":"Trước khi giữ vị trí Thư ký báo chí Nhà Trắng, bà Zacharia đã có 2 năm sống tại thủ đô Bắc Kinh (Trung Quốc) và làm việc tại Công ty Zhong Lun, một trong những hãng luật hàng đầu đất nước tỉ dân trong giai đoạn 2011 - 2013, theo báo South China Morning Post (SCMP). “Đó là giai đoạn nhiều hãng luật hàng đầu Trung Quốc tích cực mở rộng hoạt động quốc tế và tuyển dụng các luật sư được đào tạo ở nước ngoài để hỗ trợ những công việc xuyên biên giới”, ông Sida Liu, giáo sư luật và xã hội học tại Đại học Hongkong, cho biết.","k":"p"},{"t":"Bên cạnh kinh nghiệm trong lĩnh vực luật quốc tế, bà Zacharia từng đảm nhận công việc gây quỹ và truyền thông tại một tổ chức phi lợi nhuận tập trung hỗ trợ con em của lao động nhập cư. Sau thời gian ở Trung Quốc, bà gia nhập giới chính trị bảo thủ tại Mỹ. Trong năm 2026, bà từng có thời gian đảm nhận cương vị phát ngôn viên và Phó trợ lý Bộ trưởng Phụ trách Công vụ tại Bộ An ninh Nội địa Mỹ (DHS).","k":"p"},{"t":"Ngoài ra, bà Zacharia cũng là gương mặt quen thuộc trên các kênh truyền hình lớn như Fox News và Newsmax.","k":"p"},{"t":"Khả năng giao tiếp tiếng Trung","k":"h"},{"t":"Sau thời gian làm việc tại Bắc Kinh, bà Zacharia có thể giao tiếp bằng tiếng Trung và có thể duy trì một phần khả năng ngôn ngữ sau khi rời Trung Quốc.","k":"p"},{"t":"Theo các thông tin được công bố, khả năng tiếng Trung của bà Zacharia đủ để bà xen vào cuộc trò chuyện và khiến đối phương bất ngờ. Đây là điều không phải lúc nào cũng phổ biến trong giới quan chức phụ trách truyền thông chính trị tại Washington. Các chuyên gia cho rằng khoảng thời gian làm việc ở Bắc Kinh, kết hợp với khả năng ngôn ngữ có thể giúp bà Zacharia hiểu biết sâu sắc hơn về văn hóa Trung Quốc và những động lực của giới kinh doanh nước này.","k":"p"},{"t":"Ông Denis Simon, nghiên cứu viên cao cấp tại Viện Quincy (Washington), nhận định kinh nghiệm sống ở Bắc Kinh có thể mang lại cho bà Zacharia “một góc nhìn hữu ích”.","k":"p"},{"t":"“Bà ấy có cơ hội tiếp xúc với Trung Quốc thông qua lĩnh vực luật thương mại và công việc tại tổ chức phi lợi nhuận, thay vì chỉ nhìn nhận nước này qua các cuộc tranh luận chính trị ở Mỹ”, ông Simon bình luận.","k":"p"}]},{"id":9,"cat":"Văn hóa","emoji":"🎨","title":"Hoàng Võ và niềm vui \u0027Xuân thì\u0027","sapo":"Từ những thiếu nữ trong tranh sơn dầu, sáp dầu, chì than đến những phong cảnh màu nước và acrylic phóng khoáng, triển lãm \u0027Xuân thì 2026\u0027 cho thấy một Hoàng Võ vẫn luôn hào hứng với những tìm tòi, \u0027nghịch ngợm\u0027 mới sau nhiều năm cầm cọ.","body":[{"t":"Một góc tranh thiếu nữ vẽ sáp dầu theo lối sơn dầu của Hoàng Võ tại triển lãm - Ảnh: H.VY","k":"cap"},{"t":"Trưng bày từ nay đến 17-10 tại 3B Gallery (TP.HCM), triển lãm Xuân thì 2026 giới thiệu hơn 70 tác phẩm được họa sĩ Hoàng Võ sáng tác trong khoảng một năm qua.","k":"p"},{"t":"Đây là triển lãm cá nhân thứ tư của Hoàng Võ trong 10 năm, cũng là lần đầu anh chọn một phòng tranh tư nhân làm nơi giới thiệu tác phẩm.","k":"p"},{"t":"Triển lãm trưng bày từ nay đến 17-10 tại 3B Gallery (TP.HCM)","k":"cap"},{"t":"Vẽ để được chơi đùa cùng chất liệu","k":"h"},{"t":"Với Hoàng Võ, việc chọn ngôi nhà xưa của danh họa Nguyễn Gia Trí làm nơi trưng bày mang đến nhiều cảm hứng. Những căn phòng với không gian riêng cho phép anh sắp xếp tranh theo từng chất liệu, đề tài khác nhau mà không tạo cảm giác rời rạc.","k":"p"},{"t":"Ở đó, những thiếu nữ xuân thì của Hoàng Võ hiện lên qua nhiều chất liệu, màu sắc và dáng hình đa dạng. Có bức mang vẻ đẹp đầy đặn, dịu dàng của sơn dầu, có bức tươi tắn, tinh nghịch với sáp dầu.","k":"p"},{"t":"Với Hoàng Võ, được vẽ đã là niềm vui. Và khi niềm vui ấy có thể lan sang người xem, đến những học trò hay đồng nghiệp, anh xem đó là phần đóng góp nhỏ của mình vào dòng chảy mỹ thuật đương đại","k":"p"},{"t":"Xen giữa nhiều hình thể ấy là những phong cảnh màu nước nhỏ nhắn, mở ra những khoảng trời tự do thoáng rộng trong thế giới hội họa của Hoàng Võ. Niềm vui mỗi ngày được vẽ chính là động lực để anh không ngừng làm mới mình.","k":"p"},{"t":"Bên cạnh những chất liệu quen thuộc như sơn dầu, acrylic và màu nước, Hoàng Võ dành nhiều tâm sức cho sáp dầu, chất liệu anh khai thác vượt khỏi tính phác thảo thông thường.","k":"p"},{"t":"Vẽ thiếu nữ bằng sáp dầu không dễ bởi người vẽ phải thể hiện cho được vẻ mềm mại, tươi trẻ của hình thể. Hoàng Võ thử nghiệm hai hướng xử lý: một cách gợi sắc độ trầm, có phần sang và buồn của sơn dầu; cách còn lại trong trẻo, tinh nghịch như màu nước.","k":"p"},{"t":"Họa sĩ Hoàng Võ bên loạt tranh phác thảo bằng than chì - Ảnh: H.VY","k":"cap"},{"t":"Với anh, niềm vui không chỉ đến từ việc tìm ra hiệu quả thị giác mới mà còn từ cảm giác được vẽ theo cách riêng. Vì thế, những bức tranh sáp dầu của anh đầy tươi tắn, bay bổng, nhảy nhót như chính sự vui đùa hồn nhiên trong quá trình sáng tác.","k":"p"},{"t":"Ở chất liệu sơn dầu, dù đã nhiều kinh nghiệm, anh vẫn tự đặt ra những thử thách mới với hình thể thiếu nữ. Còn với than, những phác thảo dáng người được thực hiện nhanh, tự do, dứt khoát, phát huy sở trường hình họa mà anh tích lũy qua nhiều năm giảng dạy.","k":"p"},{"t":"Nét đẹp thiếu nữ xuân thì được thể hiện trân trọng, nâng niu trong tranh Hoàng Võ - Ảnh: H.VY","k":"cap"},{"t":"Nhà nghiên cứu mỹ thuật Cường Quách nhận xét phía sau vẻ tự nhiên trong tranh Hoàng Võ là nền tảng nghề nghiệp vững vàng. Hiểu cấu trúc hình thể, anh có thể giản lược hoặc phá vỡ hình; nắm được sắc độ, anh có thể để màu sắc chuyển động tự do.","k":"p"},{"t":"Đó cũng là điều đáng chú ý ở Xuân thì 2026, khi kinh nghiệm không khiến người vẽ chỉ tìm đến những gì đã thành thạo mà trở thành điểm tựa để anh tiếp tục thử nghiệm.","k":"p"},{"t":"Một góc tranh phong cảnh màu nước","k":"cap"},{"t":"Từ thiếu nữ đến những khoảng trời riêng","k":"h"},{"t":"Nếu hình tượng thiếu nữ là điểm nhấn của Xuân thì 2026, loạt phong cảnh màu nước lại mở ra một hướng đi đáng chú ý. Đây là đề tài Hoàng Võ đã thực hành từ lâu nhưng ít khi giới thiệu. Lần này, anh thấy mình đã hiểu rõ chất liệu, từ cách điều phối màu sắc đến tổ chức không gian trong một diện tích nhỏ.","k":"p"},{"t":"Những tranh phong cảnh kích thước nhỏ nhưng đủ đầy bố cục, sắc độ, chiều sâu và hiệu ứng loang màu. Những khổ panorama với chiều ngang rộng đặt ra thử thách: làm sao vừa thoáng vừa không khiến cảnh vật dàn trải, vẫn đủ mênh mông cả chiều cao và chiều sâu.","k":"p"},{"t":"Một bức tranh màu nước khổ panorama của Hoàng Võ","k":"cap"},{"t":"Đặc biệt, thay vì tái hiện một nơi chốn cụ thể, anh chỉ giữ lại cảm giác về cảnh vật trong tranh.","k":"p"},{"t":"\"Tôi đi vẽ ngoại cảnh nhiều nơi nhưng không chủ trương vẽ lại địa danh với vị trí rõ ràng, cụ thể. Tôi muốn vẽ lãng mạn, hơi trừu tượng một chút để mỗi người xem đều có thể tìm thấy sự thân thuộc theo cảm nhận của riêng mình\", Hoàng Võ nói.","k":"p"},{"t":"Góc tác phẩm phong cảnh bằng chất liệu acrylic","k":"cap"},{"t":"Họa sĩ Phan Trọng Văn nhìn thấy ở Hoàng Võ sự dịch chuyển từ hình họa đến tự do của màu sắc, từ cơ thể con người đến những trạng thái hội họa. Nếu tranh thiếu nữ đem lại cảm giác đầy đặn, mực thước, thì phong cảnh màu nước lại mang vẻ phóng khoáng, trữ tình khác.","k":"p"},{"t":"Sự chuyển đổi giữa các chất liệu cũng giúp triển lãm không bị bó hẹp trong câu chuyện về tuổi trẻ. Từ hình thể đến thiên nhiên, \"xuân thì\" còn là sức sống của cảnh vật, của màu sắc và khả năng rung động trước cái đẹp của người họa sĩ.","k":"p"},{"t":"Một bức tranh màu nước trên canvas đòi hỏi nhiều công phu","k":"cap"},{"t":"Khi vẽ, Hoàng Võ không đặt nặng những tuyên ngôn lớn lao. Anh chỉ mong mỗi lần giới thiệu tranh là một lần có thêm điều mới mẻ, cả trong tác phẩm lẫn cách làm nghề. Đây cũng là cách anh tiếp thêm động lực cho những bạn trẻ mà mình yêu mến.","k":"p"},{"t":"\"Thầy lớn tuổi rồi mà còn vẽ, tụi bây sao không vẽ? Trời cho biết vẽ là vui lắm, \u0027đã thấy mồ\u0027, vẽ đi!\", anh hóm hỉnh chia sẻ.","k":"p"},{"k":"cap","t":"Triển lãm \"Xuân thì 2026\" của họa sĩ Hoàng Võ"}]},{"id":10,"cat":"Văn hóa","emoji":"🎭","title":"NSND Xuân Bắc- NSND Tự Long cùng tham gia chương trình nghệ thuật “Chắp cánh tuổi thơ”","sapo":"Lấy thiếu nhi làm trung tâm, chương trình nghệ thuật \u0027Chắp cánh tuổi thơ\u0027 kết nối âm nhạc, nghệ thuật biểu diễn giúp các em khám phá thế giới, cảm nhận những giá trị của gia đình, quê hương và có thêm động lực học tập, rèn luyện để thực hiện ước mơ. NSND Xuân Bắc-Tự Long cùng tham gia chương trình nghệ thuật này.","body":[{"t":"NSND Tự Long- NSND Xuân Bắc cùng tham gia chương trình nghệ thuật “Chắp cánh tuổi thơ” (ảnh BTC).","k":"cap"},{"t":"Chiều 6/10/2026, Báo Nhân Dân tổ chức lễ công bố chương trình nghệ thuật “Chắp cánh tuổi thơ” với chủ đề “Hành trình của ước mơ và những khám phá diệu kỳ.”","k":"p"},{"t":"Chương trình sẽ diễn ra vào 16h ngày 10/10/2026 tại Trung tâm Hội nghị Quốc gia, Hà Nội nhân kỷ niệm 72 năm Ngày Giải phóng Thủ đô 10/10.","k":"p"},{"t":"Phát biểu tại Lễ công bố, ông Quế Đình Nguyên, Phó Tổng Biên tập Báo Nhân Dân cho hay chăm lo cho thiếu nhi là trách nhiệm chung của gia đình, nhà trường và toàn xã hội. Bằng thế mạnh của báo chí, văn hóa và nghệ thuật, Báo Nhân Dân mong muốn góp thêm những sản phẩm lành mạnh, giàu tính giáo dục và nhân văn, phù hợp với nhu cầu và cách tiếp nhận của các em.","k":"p"},{"t":"Ông Quế Đình Nguyên, Phó Tổng Biên tập Báo Nhân Dân chia sẻ về chương trình (Ảnh: BTC).","k":"cap"},{"t":"Việc tạo ra một không gian nghệ thuật riêng biệt như \"Chắp cánh tuổi thơ\" không chỉ nhằm mang đến niềm vui, mà sâu xa hơn, chính là cách Báo Nhân Dân nuôi dưỡng thế hệ bạn đọc tương lai của mình.","k":"p"},{"t":"Với hình tượng “Trang giấy diệu kỳ” làm ngôn ngữ sáng tạo xuyên suốt, chương trình bắt đầu từ một hình ảnh thân thuộc với trẻ em: Trang giấy trắng bên bàn học. Từ những nét vẽ, nếp gấp và trí tưởng tượng, trang giấy lần lượt mở ra những thế giới mới, khi trở thành chiếc máy bay, khi hóa thành con thuyền, mang theo những ước mơ của trẻ nhỏ qua từng chặng hành trình.","k":"p"},{"t":"Đồng hành cùng các em là hai nhân vật Sao Đỏ và Sao Băng, do Mạc Văn Khoa và Hoàng Kim Ngọc đảm nhận. Sao Đỏ là người anh ấm áp, hiểu biết; còn Sao Băng, từ sự rụt rè ban đầu, từng bước trở nên tự tin hơn qua mỗi trải nghiệm. Sự thay đổi của nhân vật góp phần thể hiện hành trình khám phá và trưởng thành của các em nhỏ.","k":"p"},{"t":"Lấy thiếu nhi làm trung tâm, chương trình nghệ thuật \u0027Chắp cánh tuổi thơ\u0027 kết nối âm nhạc, nghệ thuật biểu diễn giúp các em khám phá thế giới (Ảnh: BTC).","k":"cap"},{"t":"Bên cạnh các tiết mục nghệ thuật, NSND Xuân Bắc và NSND Tự Long sẽ giao lưu, tương tác cùng khán giả nhỏ tuổi với vai trò khách mời đặc biệt. Chương trình cũng có phần trình diễn và giao lưu của Nguyễn Ngọc Phát (Phát Freestyle), người bốn lần liên tiếp vô địch bóng đá nghệ thuật Việt Nam, từng lọt Top 10 thế giới năm 2018 và Top 3 châu Á.","k":"p"},{"t":"Trước giờ biểu diễn, khán giả nhỏ tuổi có thể tham gia hoạt động trải nghiệm “Hành trình tuổi thơ” tại sảnh Trung tâm Hội nghị Quốc gia với các trò chơi, đố vui nhận quà.","k":"p"},{"t":"Chương trình sẽ được livestream trên các nền tảng mạng xã hội của Báo Nhân Dân, đưa hành trình “Chắp cánh tuổi thơ” đến với đông đảo khán giả và các gia đình trên cả nước.","k":"p"}]},{"id":11,"cat":"Thế giới","emoji":"🚀","title":"Triều Tiên vừa phóng loạt tên lửa đạn đạo ra biển Nhật Bản?","sapo":"Hàn Quốc và Nhật Bản đồng loạt thông báo Triều Tiên đã phóng nhiều tên lửa đạn đạo ra biển Nhật Bản sáng nay 12-10.","body":[{"t":"Màn hình tivi chiếu hình ảnh tư liệu về các vụ phóng tên lửa của Triều Tiên trong một chương trình thời sự tại ga Seoul (Seoul, Hàn Quốc) ngày 12-10 - Ảnh: AP","k":"cap"},{"t":"“Quân đội chúng tôi đã phát hiện nhiều tên lửa đạn đạo được phóng từ khu vực Bình Nhưỡng hướng về vùng biển phía đông (biển Nhật Bản) vào khoảng 9h20 (giờ địa phương)” - Hội đồng Tham mưu trưởng Liên quân Hàn Quốc (JCS) thông báo sáng 12-10.","k":"p"},{"t":"“Quân đội chúng tôi đã tăng cường giám sát và duy trì tình trạng cảnh giác cao độ trước khả năng có thêm các vụ phóng tiếp theo” - Seoul cho biết thêm.","k":"p"},{"t":"Bộ Quốc phòng Nhật Bản cũng độc lập xác nhận việc phát hiện 2 vụ phóng nghi là tên lửa đạn đạo. Các nguồn tin của tờ Kyodo News cho rằng những tên lửa này nhiều khả năng đã rơi bên ngoài vùng đặc quyền kinh tế của Nhật Bản.","k":"p"},{"t":"Thủ tướng Nhật Bản Takaichi Sanae đã chỉ thị các cơ quan chính phủ nỗ lực tối đa để thu thập, phân tích thông tin, nhanh chóng cung cấp thông tin chính xác cho công chúng, đồng thời bảo đảm an toàn hàng hải và an toàn không phận. Triều Tiên chưa lên tiếng về thông tin trên.","k":"p"},{"t":"Vụ phóng mới nhất diễn ra sau khi Triều Tiên phóng một tên lửa đạn đạo hôm 3-10.","k":"p"},{"t":"Theo Hãng thông tấn Trung ương Triều Tiên (KCNA), bà Kim Yo Jong - em gái của nhà lãnh đạo Kim Jong Un - khi đó cho biết tên lửa này là tên lửa chiến lược tầm trung, có khả năng bay theo quỹ đạo bất thường.","k":"p"},{"t":"Theo Hãng tin AP, vụ phóng ngày 12-10 cũng diễn ra chỉ vài ngày sau khi Hàn Quốc thử nghiệm thành công vũ khí siêu vượt âm nội địa đầu tiên vào hôm 9-10. Loại vũ khí này được thiết kế với tốc độ bay gấp ít nhất năm lần vận tốc âm thanh và có khả năng né tránh các hệ thống phòng thủ tên lửa.","k":"p"},{"t":"Tổng thống Hàn Quốc Lee Jae Myung đánh giá đây là \"một bước tiến quan trọng trong việc củng cố năng lực phòng thủ thông thường\" của Hàn Quốc.","k":"p"}]},{"id":12,"cat":"Thế giới","emoji":"🛢️","title":"Mỹ giải thích 2 cách về việc mua dầu Nga; Anh cáo buộc Iran âm mưu khủng bố","sapo":"Ông Trump nói thỏa thuận mua dầu Nga là vì người Mỹ; Triều Tiên phóng thử tên lửa đạn đạo; Thẩm phán Mỹ \u0027trên cả giận dữ\u0027 khi chính phủ chặt 500 cây xanh; Anh cáo buộc IRGC đứng sau âm mưu tấn công căn cứ quân sự... là một số tin tức thế giới đáng chú ý sáng 13-10.","body":[{"t":"Tổng thống Mỹ Donald Trump (trái) và Tổng thống Nga Vladimir Putin - Ảnh: AFP","k":"cap"},{"t":"Ông Trump nói thỏa thuận mua dầu Nga là vì người Mỹ","k":"h"},{"t":"Theo Hãng tin Reuters, ngày 12-10, Tổng thống Mỹ Donald Trump kiên quyết bảo vệ thỏa thuận mua dầu Nga được ông công bố hôm 9-10.","k":"p"},{"t":"Thỏa thuận này vốn đang bị nhiều nghị sĩ từ cả hai đảng chỉ trích do vi phạm các lệnh trừng phạt năng lượng của Washington với Matxcơva. Ông Trump tuyên bố trên mạng xã hội Truth Social: \"EU đã trả cho Nga 250 tỉ USD tiền năng lượng, vậy mà giới truyền thông quen loan tin giả chẳng muốn đụng tới chuyện đó. Tôi đã đưa ra lựa chọn đúng đắn vì người dân Mỹ. Luôn luôn, nước Mỹ trên hết!\".","k":"p"},{"t":"Cùng ngày, Phó thủ tướng Nga Alexander Novak cho biết Nga có thể xuất khẩu diesel vượt mức ông Trump đưa ra.","k":"p"},{"t":"\"Đến cuối năm, xuất khẩu có thể đạt 3 - 3,5 triệu tấn/tháng, trở lại mức trước khủng hoảng\", ông nói trên kênh truyền hình nhà nước Rossiya-24.","k":"p"},{"t":"Ông Novak cũng khẳng định con số 250 tỉ USD của Mỹ bị đánh giá thấp \"đáng kể\". Theo ông, từ năm 2022, tức khi chiến sự Nga - Ukraine bùng nổ diện rộng, đến nay thì Matxcơva đã cung cấp cho EU lượng năng lượng trị giá 320,7 tỉ USD.","k":"p"},{"t":"Mỹ muốn dùng việc mua dầu để Nga xuống nước","k":"h"},{"t":"Đặc phái viên Steve Witkoff xuất hiện cùng ông Trump hôm 8-10, trước khi gặp phái đoàn Ukraine tại Miami một ngày sau đó - Ảnh: AP","k":"cap"},{"t":"Hãng tin Reuters dẫn ba nguồn tin khẳng định Đặc phái viên Nhà Trắng Steve Witkoff và ông Jared Kushner, con rể ông Trump, đã khẳng định với Ukraine rằng thỏa thuận mua dầu Nga là nỗ lực kéo Matxcơva trở lại bàn đàm phán.","k":"p"},{"t":"Tuyên bố trên được đưa ra với phái đoàn Ukraine đến làm việc với hai quan chức này tại Miami hôm 9-10.","k":"p"},{"t":"Cụ thể, phía Mỹ cho rằng ông Putin chưa sẵn sàng đàm phán chấm dứt chiến tranh. Họ tin thỏa thuận có thể \"làm mềm\" lập trường Matxcơva vì nó cho thấy ông Trump sẵn sàng có động thái với Nga. Ông Kushner cũng nhắc lại yêu cầu Kiev ngừng tập kích nhà máy lọc dầu Nga.","k":"p"},{"t":"\"Ý tưởng là Mỹ có thể quay lại nói với Nga: \u0027Thấy chưa, Ukraine đã ngừng tấn công và chúng tôi cũng cho các ông thỏa thuận này. Giờ đến lượt các ông\u0027\", một nguồn tin khẳng định.","k":"p"},{"t":"Phía Ukraine hoài nghi cách dùng thỏa thuận làm ăn để xoa dịu Nga.","k":"p"},{"t":"Một nguồn tin thân cận Điện Kremlin đã khẳng định Tổng thống Nga Vladimir Putin kiên định lập trường kiểm soát toàn bộ vùng công nghiệp Donbass (bao gồm Donetsk và Lugansk), nơi Ukraine vẫn đang giữ 11% diện tích, để làm minh chứng cho thắng lợi của \"chiến dịch quân sự đặc biệt\".","k":"p"}]},{"id":13,"cat":"Giáo dục","emoji":"🎓","title":"Bách khoa Hà Nội tuổi 70: Hơn 100 ngành học, ra mắt không gian đổi mới sáng tạo chuẩn quốc tế","sapo":"Sau 70 năm phát triển, Đại học Bách khoa Hà Nội đào tạo hơn 100 ngành học, 176 chuyên ngành và chuẩn bị vận hành không gian đổi mới sáng tạo chuẩn quốc tế.","body":[{"t":"Cổng Parabol - biểu tượng của tinh thần đột phá, độc lập và vươn cao của Đại học Bách khoa Hà Nội - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Đại học Bách khoa Hà Nội được thành lập năm 1956 do Bộ trưởng Bộ Giáo dục Nguyễn Văn Huyên ký ban hành. Đây là trường đại học kỹ thuật đầu tiên của cả nước, có nhiệm vụ đào tạo kỹ sư công nghiệp cho công cuộc xây dựng chủ nghĩa xã hội ở miền Bắc và đấu tranh giải phóng miền Nam.","k":"p"},{"t":"Ngay từ những ngày đầu thành lập, Đại học Bách khoa Hà Nội đã hội tụ những trí tuệ lớn của đất nước, như giáo sư Trần Đại Nghĩa, giáo sư Tạ Quang Bửu, nhà giáo Hoàng Xuân Tùy, giáo sư Phạm Đồng Điện, giáo sư Hà Học Trạc.","k":"p"},{"t":"Ngày 15-10-1956, trường chính thức khai giảng khóa học chính quy đầu tiên cho gần 1.000 sinh viên thuộc 14 chuyên ngành của 4 chuyên khoa đầu tiên, gồm: cơ điện, mỏ luyện kim, hóa thực phẩm và xây dựng.","k":"p"},{"t":"Năm 1960, trụ sở được khởi công xây dựng tại đường Đại Cồ Việt, với sự hỗ trợ của Liên Xô. Đây là nền tảng cho hệ thống cơ sở vật chất ngày càng khang trang, hiện đại.","k":"p"},{"t":"Sắp vận hành không gian đổi mới sáng tạo chuẩn quốc tế","k":"h"},{"t":"Toàn cảnh Không gian Đổi mới sáng tạo liên ngành - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Theo Đại học Bách khoa Hà Nội, giữa tháng 10-2026, nhà trường sẽ đưa vào vận hành Không gian Đổi mới sáng tạo liên ngành Design Factory tại tầng 6, 7, 8, tại Thư viện Tạ Quang Bửu.","k":"p"},{"t":"Không gian là một hệ sinh thái hoàn chỉnh được tạo thành bởi sự kết hợp Trung tâm Đổi mới sáng tạo liên ngành, các viện nghiên cứu và khu không gian hợp tác với các tập đoàn, doanh nghiệp.","k":"p"},{"t":"Trung tâm Đổi mới sáng tạo liên ngành của Đại học Bách khoa Hà Nội được xây dựng theo mô hình quốc tế do Đại học Aalto (Phần Lan) khởi xướng từ năm 2008 - hiện đã có mặt tại 38 trung tâm trên toàn thế giới thông qua Mạng lưới Design Factory toàn cầu. Đây là trung tâm Design Factory đầu tiên tại Việt Nam đáp ứng tiêu chuẩn của mạng lưới này.","k":"p"},{"t":"Sinh viên Bách khoa hào hứng trải nghiệm không gian học tập tại tầng 6 thuộc không gian - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Khác với các không gian sáng tạo hay phòng chế tạo thông thường, Design Factory là sự tích hợp toàn diện giữa con người - phương pháp - không gian - doanh nghiệp trong một hệ sinh thái thống nhất.","k":"p"},{"t":"Sinh viên không chỉ học kiến thức chuyên môn, mà còn được trải nghiệm toàn bộ quá trình phát triển sản phẩm - từ xác định vấn đề, tư duy thiết kế, chế tạo thử nghiệm đến đánh giá, hoàn thiện và hướng tới thương mại hóa.","k":"p"},{"t":"Tầng 7 của không gian được bố trí các khu như: nhà máy số, khu chế thử nhanh, khu kiểm thử, không gian làm việc nhóm. Tại phòng Digital Factory (nhà máy số), nhà trường trang bị hệ thống robot, điều khiển PLC, biến tần và phần mềm quản lý, điều hành sản xuất. Khu vực này còn có khoảng 30 máy tính cài đặt phần mềm phục vụ mô phỏng, vận hành quy trình sản xuất tự động trong lĩnh vực cơ khí và điện - điện tử - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Ngay trong năm 2026, Không gian Đổi mới sáng tạo liên ngành đặt mục tiêu phục vụ 10.000 lượt người học trong các môn kỹ năng bổ trợ, hỗ trợ 200 người học triển khai dự án thực tế, tạo ra 10 sản phẩm ở dạng chế thử và đăng ký 3 sáng chế.","k":"p"},{"t":"Đến năm 2030, các con số này dự kiến tăng lên 30.000 lượt sinh viên, 1.000 người thực hiện dự án, 200 sản phẩm chế thử, 30 sáng chế, cùng với 50 nhóm khởi nghiệp và 30 doanh nghiệp spinoff/start-up hình thành qua hệ sinh thái của đại học.","k":"p"},{"t":"Dọc các hành lang trong không gian được bố trí các dãy bàn, ghế để sinh viên có điều kiện học tập, nghiên cứu tốt nhất - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"GS.TS Lê Anh Tuấn - Giám đốc Đại học Bách khoa Hà Nội - cho biết Không gian Đổi mới sáng tạo liên ngành là nơi hiện thực hóa mô hình hợp tác “ba nhà” - nhà trường, doanh nghiệp và Nhà nước nhằm tạo ra những giá trị thực tiễn phục vụ sự phát triển của đất nước.","k":"p"},{"t":"Với không gian mở, kích thích sáng tạo, sinh viên có thể nghiên cứu, hoàn thiện sản phẩm và đo kiểm để hoàn thiện và đưa sản phẩm ra thị trường.","k":"p"},{"t":"70 năm đào tạo nhân lực cho đất nước, hơn 300.000 cựu sinh viên","k":"h"},{"t":"Hiện nay, sức mạnh của một quốc gia được đo bằng năng lực sáng tạo tri thức, làm chủ công nghệ và khả năng tạo ra những giá trị mới. Nghị quyết 57 của Bộ Chính trị cũng đã xác định khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số là động lực đột phá hàng đầu để phát triển nhanh và bền vững.","k":"p"},{"t":"Đại học Bách khoa Hà Nội đang ưu tiên 5 lĩnh vực nghiên cứu, gồm: Trí tuệ nhân tạo và công nghệ dữ liệu, khoa học và công nghệ sức khỏe, vật liệu mới, năng lượng và môi trường bền vững, hệ thống thông minh.","k":"p"},{"t":"Với gần 200 phòng thí nghiệm, bao gồm các phòng thí nghiệm trọng điểm quốc gia và các phòng thí nghiệm trọng điểm cấp bộ, tại đây sinh viên được thỏa sức nghiên cứu, thử nghiệm với các lĩnh vực mũi nhọn.","k":"p"},{"t":"Sinh viên Đại học Bách khoa Hà Nội thực hành trong phòng thí nghiệm - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Trước đó, ngày 2-12-2022, Thủ tướng Chính phủ quyết định chuyển Trường đại học Bách khoa Hà Nội thành Đại học Bách khoa Hà Nội để có những bước phát triển mới.","k":"p"},{"t":"Đến năm 2024, Đại học Bách khoa Hà Nội đã hình thành 6 trường, 6 viện nghiên cứu, 4 khoa. Tổng số đầu mối là 40 đơn vị.","k":"p"},{"t":"Sau 7 thập kỷ, hiện Đại học Bách khoa Hà Nội có khoảng 300.000 cựu sinh viên trên toàn thế giới. Trường đang đào tạo hơn 100 ngành học, 176 chuyên ngành từ bậc cử nhân đến tiến sĩ. Hiện quy mô đào tạo của trường khoảng 42.000 sinh viên, học viên mỗi năm.","k":"p"},{"t":"Đại học Bách khoa Hà Nội cũng đã triển khai đề án thu hút các nhà khoa học trẻ xuất sắc từ các trường đại học và viện nghiên cứu hàng đầu thế giới trở về trường giảng dạy, xây dựng các nhóm nghiên cứu mạnh, phát triển hệ thống phòng thí nghiệm hiện đại, tạo môi trường học thuật nuôi dưỡng những tài năng học thuật của Việt Nam.","k":"p"},{"t":"Những tấm bảng huyền thoại kín chữ trong mỗi tiết học tại Bách khoa Hà Nội - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Sinh viên Đại học Bách khoa Hà Nội trong giờ học - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Đại học Bách khoa Hà Nội sở hữu khuôn viên với tổng diện tích hơn 26ha, lớn nhất trong các trường đại học khu vực nội thành Hà Nội. Gần nửa năm qua, với sự chỉ đạo quyết liệt của ban giám đốc và sự đồng lòng của tập thể cán bộ, giảng viên, diện mạo khuôn viên, không gian học tập và hệ thống cơ sở vật chất của nhà trường đã đổi thay rõ nét.","k":"p"},{"t":"Nhiều khu giảng đường tại Đại học Bách khoa Hà Nội được cải tạo, thay đổi rõ nét - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"70 năm, từ giảng đường của Đại học Bách khoa Hà Nội, đã có hơn 300.000 kỹ sư, nhà khoa học, nhà quản lý các thế hệ đã bước vào những lĩnh vực quan trọng của nền kinh tế, góp phần xây dựng, phát triển đất nước.","k":"p"},{"t":"Những nỗ lực của thầy và trò Đại học Bách khoa Hà Nội trong chặng đường 70 năm hình thành và phát triển đã được Đảng và Nhà nước ghi nhận, trao tặng nhiều phần thưởng, danh hiệu cao quý.","k":"p"},{"t":"Cựu sinh viên trở về Bách khoa Hà Nội dịp 70 năm thành lập trường - Ảnh: NGUYÊN BẢO","k":"cap"},{"t":"Năm 1963, trường được Nhà nước phong tặng Huân chương Lao động hạng nhì, năm 1996 đón nhận Huân chương Độc lập hạng nhất.","k":"p"},{"t":"Đại học Bách khoa Hà Nội 2 lần được trao tặng Huân chương Hồ Chí Minh (năm 2001 và 2016). Năm 2000, nhà trường đón nhận danh hiệu Anh hùng lao động thời kỳ đổi mới, năm 2006 đón nhận danh hiệu Anh hùng lực lượng vũ trang nhân dân...","k":"p"},{"t":"Trong hành trình thực hiện sứ mệnh tìm lời giải cho những bài toán của đất nước, thầy và trò Đại học Bách khoa Hà Nội vẫn luôn nhắc nhớ về lòng biết ơn. Mỗi sinh viên năm thứ nhất của Đại học Bách khoa Hà Nội sẽ được dự lễ chào (ít nhất một lần) trước tượng đài \u0027Cán bộ, sinh viên xếp bút nghiên lên đường bảo vệ Tổ quốc\u0027. Đến ngày tốt nghiệp, các em lại mang những bó hoa được tặng đến tượng đài, tri ân những người đã từ Bách khoa lên đường bảo vệ Tổ quốc và không trở về","k":"p"},{"k":"cap","t":"Đại học Bách khoa Hà Nội bước vào năm thứ 70"}]},{"id":14,"cat":"Sức khỏe","emoji":"🧠","title":"Ăn nhiều bất thường rồi tự gây nôn để tránh tăng cân, dấu hiệu của bệnh tâm thần?","sapo":"Ăn lượng lớn thức ăn trong thời gian ngắn, sau đó tự gây nôn, dùng thuốc nhuận tràng hoặc tập luyện quá mức để tránh tăng cân có thể là biểu hiện của chứng ăn vô độ tâm thần. Bệnh có thể gây ảnh hưởng nghiêm trọng đến sức khỏe.","body":[{"t":"Viện Sức khỏe tâm thần, Bệnh viện Bạch Mai chia sẻ về ăn vô độ tâm thần - Ảnh: TUẤN ANH","k":"cap"},{"t":"Ngày 12-10, Viện Sức khỏe tâm thần, Bệnh viện Bạch Mai tổ chức buổi cung cấp thông tin về chứng ăn vô độ tâm thần (Bulimia nervosa), một rối loạn ăn uống ảnh hưởng nghiêm trọng đến sức khỏe thể chất và tinh thần.","k":"p"},{"t":"Ăn vô độ gần như mỗi ngày, có lần nôn đến ngất xỉu","k":"h"},{"t":"ThS.BS Phạm Thị Nguyệt Nga, Viện Sức khỏe tâm thần, cho biết một bệnh nhân nữ 21 tuổi, sinh viên đại học, đến khám vì thường xuyên ăn lượng lớn thức ăn rồi tự gây nôn.","k":"p"},{"t":"Theo người nhà, bệnh nhân vốn trầm tính, ít chia sẻ. Khi lên đại học, cô thường bị bạn bè chê bai ngoại hình, từ đó chú ý nhiều hơn đến cân nặng, nhịn ăn và sử dụng trà, cà phê với mục đích giảm cân. Áp lực học tập, quan hệ bạn bè và gia đình khiến tình trạng ngày càng nghiêm trọng. Bệnh nhân xuất hiện các cơn ăn nhiều mất kiểm soát, thường ăn nhiều cơm, thịt, cá, bánh quy, khoai tây chiên và đồ ăn vặt. Sau khi ăn, dù cảm thấy thoải mái hơn, cô lại tự gây nôn và tập luyện quá mức để tránh tăng cân.","k":"p"},{"t":"Tần suất các cơn ăn vô độ tăng lên 8-10 lần mỗi tuần, sau đó gần như xảy ra hằng ngày. Bệnh nhân còn sử dụng thuốc nhuận tràng, thuốc lợi tiểu. Tình trạng kéo dài gây ảnh hưởng đến việc học tập, gây rối loạn kinh nguyệt, khoảng ba tháng mới có kinh một lần.","k":"p"},{"t":"Khi thăm khám, bệnh nhân có chỉ số khối cơ thể (BMI) 17,6 và hạ kali máu. Cô được chẩn đoán ăn vô độ tâm thần kèm hạ kali máu.","k":"p"},{"t":"ThS Ngô Tuấn Khiêm, Viện sức khỏe tâm thần cũng chia sẻ trường hợp nam sinh viên 22 tuổi có hơn một năm thường xuyên ăn lượng thức ăn lớn bất thường, có lúc gấp ba lần bình thường, rồi tự móc họng gây nôn.","k":"p"},{"t":"Có lần nôn nhiều đến ngất xỉu, bệnh nhân được đưa đến bệnh viện và phát hiện hạ kali máu do rối loạn điện giải. Sau đó, nam sinh cũng được chẩn đoán ăn vô độ tâm thần.","k":"p"},{"t":"Sau một tháng điều trị bằng thuốc kết hợp can thiệp tâm lý, tình trạng người bệnh cải thiện khoảng 50-60%. Qua 4-5 lần tái khám tiếp theo, bệnh nhân ổn định hơn, không còn những đợt ăn quá mức rồi gây nôn như trước.","k":"p"},{"t":"Theo bác sĩ, phát hiện và điều trị sớm giúp người bệnh cải thiện triệu chứng, kiểm soát bệnh lâu dài và hạn chế biến chứng nguy hiểm.PGS.TS Nguyễn Văn Tuấn, Viện trưởng Viện Sức khỏe tâm thần, cho biết ăn vô độ tâm thần là rối loạn ăn uống đặc trưng bởi những đợt ăn lượng thức ăn lớn bất thường, đi kèm cảm giác mất kiểm soát. Sau đó, người bệnh lặp lại các hành vi bù trừ nhằm ngăn tăng cân như tự gây nôn, lạm dụng thuốc nhuận tràng hoặc thuốc lợi tiểu, nhịn ăn và tập thể dục quá mức. Bác sĩ Khiêm cảnh báo chứng ăn vô độ tâm thần có thể gây tổn thương răng, thực quản, tuyến nước bọt, thận và đường tiêu hóa. Đặc biệt, tự gây nôn và lạm dụng thuốc lợi tiểu, nhuận tràng có thể gây rối loạn điện giải. Hạ kali máu có thể dẫn đến yếu cơ, ngất, rối loạn nhịp tim, thậm chí tử vong.","k":"p"},{"t":"Bệnh cũng có thể đi kèm trầm cảm, lo âu và các vấn đề sức khỏe tâm thần khác như trầm cảm, tự hại.","k":"p"},{"t":"\"Do xấu hổ, sợ bị phán xét hoặc cho rằng mình thiếu ý chí, nhiều người giấu kín triệu chứng và trì hoãn điều trị.","k":"p"},{"t":"Vì vậy, gia đình cần lưu ý các dấu hiệu như người bệnh thường xuyên vào nhà vệ sinh ngay sau bữa ăn, ăn uống bí mật, ăn kiêng khắt khe xen kẽ những đợt ăn mất kiểm soát, tập luyện cưỡng bức hoặc sử dụng thuốc nhuận tràng, thuốc lợi tiểu.","k":"p"},{"t":"Khi nhận thấy những biểu hiện này, người thân nên lắng nghe, tránh trách móc, đồng thời khuyến khích người bệnh đến cơ sở chuyên khoa để được đánh giá và điều trị\", bác sĩ Khiêm khuyến cáo","k":"p"}]},{"id":15,"cat":"Pháp luật","emoji":"🚓","title":"Công an mời làm việc nam sinh 16 tuổi đăng video dàn dựng vụ tai nạn giao thông","sapo":"Một nam sinh 16 tuổi ở Hưng Yên bị công an mời làm việc, sau khi đăng video dàn dựng hiện trường giả vụ tai nạn giao thông lên mạng xã hội để giải trí.","body":[{"t":"Công an xã Thái Thụy, tỉnh Hưng Yên làm việc với nam sinh 16 tuổi - Ảnh: Công an xã Thái Thụy","k":"cap"},{"t":"Trao đổi với phóng viên Tuổi Trẻ tối 12-10, một lãnh đạo Công an xã Thái Thụy (tỉnh Hưng Yên) cho biết đơn vị này đã làm việc với nam sinh T.A.T. (16 tuổi, trú xã Thái Ninh) liên quan việc đăng video dàn dựng hiện trường giả tai nạn giao thông lên mạng xã hội.","k":"p"},{"t":"Theo Công an xã Thái Thụy, đầu tháng 9-2026, T. dùng điện thoại quay cảnh một chiếc xe điện bị đổ, bên trên có người nằm đắp chăn, tại tuyến đường thuộc khu đô thị Diêm Điền Riverside, thôn Mai Diêm, xã Thái Thụy. Sau đó T. lồng ghép âm nhạc và đăng video lên mạng xã hội.","k":"p"},{"t":"Tại buổi làm việc, T. khai thực hiện hành vi trên nhằm mục đích giải trí cá nhân, không bị ai xúi giục hay ép buộc. Sau khi được công an giải thích, T. nhận thức việc đăng tải hình ảnh dàn dựng hiện trường tai nạn có thể gây hiểu nhầm, khiến dư luận hoang mang. T. đã tự nguyện gỡ bỏ video và cam kết chấp hành các quy định pháp luật khi sử dụng mạng xã hội.","k":"p"},{"t":"Công an xã Thái Thụy khuyến cáo người dân cần kiểm chứng thông tin từ các nguồn đáng tin cậy trước khi chia sẻ, không lan truyền những hình ảnh, video chưa được xác thực, tránh gây hoang mang trong cộng đồng.","k":"p"}]},{"id":16,"cat":"Thế giới","emoji":"📵","title":"Hy Lạp đề xuất cấm trẻ dưới 15 tuổi dùng Instagram, TikTok, Facebook","sapo":"Instagram, TikTok và Facebook có thể phải xác minh độ tuổi người dùng theo dự luật mới của Hy Lạp, dự kiến áp dụng từ đầu năm 2027.","body":[{"t":"Hy Lạp lên kế hoạch siết tuổi sử dụng Instagram, TikTok và Facebook - Ảnh: REUTERS","k":"cap"},{"t":"Hy Lạp ngày 12-10 đã công bố kế hoạch thiết lập một khung pháp lý mới nhằm cấm trẻ em dưới 15 tuổi truy cập vào các dịch vụ mạng xã hội như Instagram, TikTok và Facebook.","k":"p"},{"t":"Dự luật dự kiến chính thức có hiệu lực từ ngày 1-1-2027 nhằm góp phần định hình chính sách bảo vệ trẻ em trên không gian mạng ở quy mô toàn châu Âu.","k":"p"},{"t":"Những quy định chính đã được Bộ trưởng Văn phòng Chính phủ Akis Skertsos, Bộ trưởng Y tế Adonis Georgiadis và Bộ trưởng Quản trị Kỹ thuật số Dimitris Papastergiou trình bày. Dự luật sẽ được các ủy ban quốc hội xem xét vào ngày 13-10, trước khi đưa ra phiên thảo luận toàn thể và bỏ phiếu vào ngày 22-10 tới.","k":"p"},{"t":"Mốc thời gian áp dụng từ năm 2027 nhằm tạo khoảng đệm cần thiết để các công ty công nghệ chuẩn bị cơ sở hạ tầng đáp ứng.Điểm cốt lõi của dự luật mới tại Hy Lạp là chuyển nghĩa vụ kiểm soát truy cập từ phía phụ huynh sang trực tiếp các nền tảng mạng xã hội. Các công ty phải áp dụng những giải pháp xác minh độ tuổi phù hợp, đáng tin cậy và không mang tính hình thức.Để thực thi, Hy Lạp giới thiệu cơ chế xác minh thông qua ứng dụng Kids Wallet và Gov.gr Wallet. Dù vậy, dự luật vẫn tuân thủ nguyên tắc \"trung lập về công nghệ\", cho phép các doanh nghiệp tự lựa chọn giải pháp kỹ thuật riêng nếu đáp ứng đầy đủ quy chuẩn của Liên minh châu Âu (EU).","k":"p"},{"t":"Các cơ chế kiểm tra sẽ vận hành dựa trên thẻ định danh độ tuổi kỹ thuật số. Công nghệ này cho phép các nền tảng xác nhận người dùng đủ điều kiện độ tuổi mà không cần thu thập hay truy cập vào dữ liệu định danh đầy đủ cùng thông tin nhạy cảm của trẻ em. Hệ thống phải đảm bảo hoạt động hiệu quả trong điều kiện thực tế, dễ tiếp cận và có các lớp bảo vệ chống lách luật.","k":"p"},{"t":"Dự luật được xây dựng trong khung quy định của Đạo luật Dịch vụ kỹ thuật số châu Âu (DSA), đặc biệt là Điều 28 về bảo vệ trẻ vị thành niên trực tuyến. Việc giám sát sẽ được thực thi thông qua cơ chế hợp tác xuyên biên giới giữa các quốc gia thành viên EU và Ủy ban châu Âu.","k":"p"},{"t":"Tại Hy Lạp, Ủy ban quốc gia về bưu chính viễn thông (EETT) đóng vai trò điều phối chính, phối hợp cùng Hội đồng quốc gia về truyền hình và phát thanh (ESR) và Cơ quan bảo vệ dữ liệu cá nhân. Quy trình kiểm tra có thể được kích hoạt từ báo cáo của người dùng hoặc thông báo từ các cơ quan hữu quan.","k":"p"},{"t":"Nếu nền tảng vi phạm có trụ sở tại quốc gia EU khác, hồ sơ sẽ được chuyển giao cho chính quyền nước sở tại xử lý.","k":"p"}]},{"id":17,"cat":"Công nghệ","emoji":"📱","title":"IPhone 18 ế hàng, Apple phải cắt giảm đơn hàng linh kiện","sapo":"Apple đã cắt giảm đơn đặt hàng linh kiện ít nhất 15% trong tháng 10, do nhu cầu thị trường yếu hơn dự kiến.","body":[{"t":"Nhu cầu đặt mua iPhone 18 Pro và Pro Max ít hơn kỳ vọng do giá bán tăng cao - Ảnh: Getty Images","k":"cap"},{"t":"Ngày 10-10, tạp chí Nikkei Asia dẫn một số nguồn thạo tin khẳng định Apple vừa phải cắt giảm các đơn hàng linh kiện, do doanh số hai dòng iPhone 18 Pro và Pro Max ế ẩm.","k":"p"},{"t":"Nhu cầu thị trường giảm do \"bão chip\"","k":"h"},{"t":"Cụ thể, Apple đã bắt đầu dè dặt hơn trong việc đặt hàng linh kiện từ đầu tháng 9. Hai nguồn tin khẳng định các đơn đặt hàng linh kiện tháng 10 đã giảm ít nhất 15% so với ban đầu, đều do nhu cầu thị trường yếu hơn kỳ vọng.","k":"p"},{"t":"\"Chỉ riêng trong tháng 10, chúng tôi thấy đơn hàng của Apple cho cả hai mẫu cao cấp giảm 15 - 20%. Chúng tôi không biết tình hình sẽ diễn biến thế nào từ đây\", lãnh đạo một nhà cung cấp cho biết.","k":"p"},{"t":"Do thời gian sản xuất của mỗi bên khác nhau, việc cắt giảm đơn hàng sẽ chỉ ảnh hưởng đến sản lượng trong tháng 10 của một số nhà cung cấp, chứ không phải tất cả. Hiện vẫn chưa rõ Apple có tiếp tục điều chỉnh từ tháng 11 trở đi hay không.Tình hình hiện tại xuất phát từ việc Apple đã buộc phải tăng giá sản phẩm do giá đầu vào linh kiện chip tăng, khiến nhu cầu thị trường giảm mạnh.","k":"p"},{"t":"Giá niêm yết của iPhone 18 Pro Max năm nay đã tăng 100 USD so với dòng 17 Pro Max tiền nhiệm, từ 1.199 USD lên thành 1.299 USD. Tình hình tương tự diễn ra giữa dòng iPhone 17 Pro và iPhone 18 Pro.","k":"p"},{"t":"Dù tăng giá, thế hệ iPhone mới được đánh giá không có khác biệt vượt trội so với thế hệ trước, khiến lượng cầu toàn thế giới giảm.","k":"p"},{"t":"Một nguyên nhân khác dẫn đến việc cắt giảm này là do Apple đã thay đổi lịch ra mắt sản phẩm.","k":"p"},{"t":"Những năm trước, Apple công bố toàn bộ dải sản phẩm điện thoại chủ lực của mình trong một sự kiện tháng 9.Tuy nhiên tháng 9 năm nay, hãng này chỉ ra mắt hai mẫu iPhone cao cấp nhất. Hai dòng thấp hơn là iPhone 18 tiêu chuẩn và iPhone Air mới dự kiến \"nhá hàng\" vào đầu năm 2027.","k":"p"},{"t":"Do đó nhu cầu linh kiện cho các mẫu này dự kiến chỉ tăng vào cuối năm 2026.","k":"p"},{"t":"Cầu giảm nhưng tăng thị phần?","k":"h"},{"t":"Các nhà báo chụp ảnh iPhone Duo - sản phẩm mới ra mắt của Apple - tại sự kiện ra mắt sản phẩm mới ở Cupertino, California (Mỹ) ngày 9-9 - Ảnh: AFP","k":"cap"},{"t":"Không chỉ Apple, thị trường smartphone toàn cầu cũng bị ảnh hưởng vì giá linh kiện tăng đột biến.","k":"p"},{"t":"Hồi tháng 8, hãng nghiên cứu thị trường IDC đã dự báo lượng smartphone xuất xưởng trên toàn cầu sẽ giảm 16,7% - mức giảm lớn nhất lịch sử giữa hai năm. Tuy nhiên giá bán trung bình lại tăng lên 27,6%. Dự kiến tình trạng này sẽ kéo dài sang năm 2027.","k":"p"},{"t":"Mặc dù vậy Apple vẫn ít nhiều chưa phải lo lắng, vì việc giảm số lượng sản phẩm vẫn chưa tác động trực tiếp đến doanh thu của Apple, do tất cả sản phẩm đều tăng giá bán ít nhất 10%.","k":"p"},{"t":"Hơn nữa, theo hãng nghiên cứu Counterpoint, Apple và Samsungvốn từ lâu tập trung vào các mẫu điện thoại cao cấp - nhiều khả năng sẽ giành thêm thị phần nhờ cơn bão giá hiện tại.","k":"p"},{"t":"Điều này là do các đối thủ nhỏ hơn của họ thường nhắm vào phân khúc giá phải chăng, vốn nhạy cảm hơn với các tác động về giá.","k":"p"},{"t":"Nhà phân tích Yang Wang của Counterpoint ước tính thị phần của mỗi hãng sẽ tăng từ mức dưới 20% năm 2025 lên hơn 22% năm 2026.","k":"p"}]},{"id":18,"cat":"Pháp luật","emoji":"📦","title":"Công an điều tra vụ nam shipper và khách nhận hàng xô xát ở Sầm Sơn","sapo":"Trong lúc giao trả hàng, nam shipper và thanh niên nhận hàng ở Sầm Sơn (Thanh Hóa) đã có mâu thuẫn dẫn tới xô xát, đánh nhau.","body":[{"t":"Hình ảnh nam shipper bị hành hung trên đường phố Sầm Sơn - Ảnh cắt từ clip","k":"cap"},{"t":"Ngày 13-10, thông tin từ Công an phường Sầm Sơn, tỉnh Thanh Hóa cho biết đơn vị đang vào cuộc điều tra vụ việc gây thương tích xảy ra trên địa bàn. Theo Công an phường Sầm Sơn, khoảng 10h15 ngày 11-10, đơn vị tiếp nhận vụ việc xô xát, gây thương tích tại đường Trần Hưng Đạo, tổ dân phố Tân Phúc, phường Sầm Sơn giữa anh L.V.T. (32 tuổi, ngụ tổ dân phố Hồng Cường, phường Sầm Sơn), làm nghề shipper và L.N.V.B. (24 tuổi, ngụ tổ dân phố Tân Phúc, phường Sầm Sơn).","k":"p"},{"t":"Nguyên nhân ban đầu được xác định do mâu thuẫn trong việc giao trả hàng và nhận tiền nên hai bên xảy ra xô xát đánh nhau. Hiện cả hai đều bị thương và đang điều trị tại bệnh viện.","k":"p"},{"t":"Công an mời thanh niên nhận hàng có xô xát với nam shipper lên cơ quan công an làm việc - Ảnh: Công an Sầm Sơn","k":"cap"},{"t":"Trước đó, trên mạng xã hội Facebook lan truyền đoạn clip ghi lại cảnh nam shipper (người giao hàng) liên tục bị một thanh niên đấm vào mặt khiến nhiều người bức xúc.","k":"p"},{"t":"Qua hình ảnh cho thấy nam shipper đến giao hàng cho khách thì hai bên xảy ra cãi vã. Sau đó, người đàn ông cởi trần, mặc quần đùi liên tục hành hung nam shipper ngay trên đường phố.","k":"p"},{"t":"Hiện Công an phường Sầm Sơn đang tiến hành thu thập hồ sơ, tài liệu xử lý theo quy định của pháp luật.","k":"p"}]},{"id":19,"cat":"Sức khỏe","emoji":"🥬","title":"5 thực phẩm giàu sắt ngoài thịt đỏ, có cả món quen trong bữa cơm Việt","sapo":"Thịt đỏ thường được nhắc đến như một nguồn cung cấp sắt dồi dào. Tuy nhiên, nhiều thực phẩm quen thuộc dân dã trong bữa cơm Việt cũng có thể cung cấp lượng sắt đáng kể, tùy theo khẩu phần ăn.","body":[{"t":"Sắt là khoáng chất thiết yếu giúp cơ thể tạo hemoglobin, thành phần trong hồng cầu có nhiệm vụ vận chuyển oxy. Thịt đỏ không phải là duy nhất. Trên thực tế, nhiều loại thực phẩm bao gồm cả thực phẩm có nguồn gốc động vật và thực vật cung cấp lượng sắt nhiều hơn cả thịt đỏ.","k":"p"},{"t":"Dưới đây là 5 thực phẩm có hàm lượng sắt cao, có thể bổ sung vào chế độ ăn hằng ngày, theo Health.","k":"p"},{"t":"1. Gan gà","k":"h"},{"t":"Trong khẩu phần khoảng 85 g gan gà có tới 9,86 mg sắt, đáp ứng khoảng 54% giá trị dinh dưỡng hằng ngày. Gan gà còn cung cấp protein, vitamin và nhiều khoáng chất. Đặc biệt, sắt trong gan gà thuộc dạng sắt heme, được cơ thể hấp thụ hiệu quả hơn so với sắt không heme có trong thực vật.","k":"p"},{"k":"cap","t":"Gan gà là một trong những thực phẩm giàu sắt","img":"19-1"},{"t":"2. Hàu","k":"h"},{"t":"Hàu là một trong những thực phẩm giàu sắt. Trong 85 g hàu có 8 mg sắt, cung cấp 44% lượng sắt cần thiết hằng ngày mỗi khẩu phần.","k":"p"},{"t":"Hàu có thể giúp tăng lượng sắt hiệu quả ở những người có nhu cầu sắt cao, chẳng hạn như những người có chu kỳ kinh nguyệt nhiều hoặc có lượng sắt dự trữ thấp. Nhiều người thích ăn hàu sống. Tuy nhiên, nấu chín hàu có thể làm giảm nguy cơ nhiễm các tác nhân gây bệnh từ thực phẩm, chẳng hạn như vi khuẩn Vibrio.","k":"p"},{"k":"cap","t":"Hàu có thể giúp tăng lượng sắt hiệu quả","img":"19-2"},{"t":"3. Đậu phụ","k":"h"},{"t":"Một cốc đậu phụ (khoảng 240 g) có thể cung cấp khoảng 6 mg sắt, tương đương 34% giá trị dinh dưỡng hằng ngày. Đậu phụ không chỉ giàu protein thực vật mà còn cung cấp sắt không heme. Đây là thực phẩm dễ chế biến, có thể dùng trong các món hấp, xào, nướng hoặc thay thế một phần thịt trong bữa ăn.","k":"p"},{"k":"cap","t":"Đậu phụ là thực phẩm quen thuộc (Ảnh minh họa: L.C tạo bởi AI)","img":"19-3"},{"t":"4. Rau chân vịt","k":"h"},{"t":"Một cốc rau chân vịt theo khẩu phần được dẫn cung cấp khoảng 6 mg sắt, đáp ứng 34% giá trị dinh dưỡng hằng ngày. Để hỗ trợ hấp thụ sắt tốt hơn có thể kết hợp loại rau này với thực phẩm giàu vitamin C, chẳng hạn trộn salad cùng nước sốt có vị cam quýt hoặc thêm chanh vào món rau xào.","k":"p"},{"k":"cap","t":"Rau chân vịt kết hợp thực phẩm giàu vitamin C giúp hấp thụ sắt tốt hơn","img":"19-4"},{"t":"5. Sô cô la đen","k":"h"},{"t":"Trong 57 g sô cô la đen cung cấp 4 mg sắt, tương đương 22% giá trị dinh dưỡng hằng ngày. Hạt cacao tự nhiên chứa sắt và khi được xay thành bột cacao để làm sô cô la. Do chứa tỷ lệ ca cao cao hơn sô cô la sữa, sô cô la đen thường cung cấp nhiều sắt hơn, cùng với một số khoáng chất khác. Tuy nhiên, đây vẫn là thực phẩm giàu năng lượng, vì vậy nên chú ý khẩu phần và ưu tiên loại ít đường bổ sung.","k":"p"},{"k":"cap","t":"Sô cô la đen cung cấp nhiều sắt hơn sô cô la sữa","img":"19-5"},{"t":"Nếu cơ thể thiếu sắt hoặc mắc bệnh thiếu máu do thiếu sắt, việc chỉ tăng cường thực phẩm giàu sắt trong chế độ ăn có thể không đủ để đưa lượng sắt trở về mức bình thường. Trong nhiều trường hợp, người bệnh cần bổ sung sắt bằng thuốc theo chỉ định của bác sĩ, kết hợp với chế độ ăn giàu sắt để khôi phục và duy trì lượng sắt dự trữ cần thiết cho cơ thể.","k":"p"}]},{"id":20,"cat":"Xe","emoji":"🚗","title":"Ô tô hybrid hút khách giữa lúc xăng tăng giá, xe Toyota bán chạy nhất","sapo":"Sức mua trên thị trường ô tô hồi phục ngay đúng lúc giá xăng, dầu liên tục leo thang mở ra cơ hội thúc đẩy lượng tiêu thụ ô tô hybrid tăng trưởng, trong đó phần lớn người Việt mua ô tô hybrid đề cao yếu tố tiết kiệm, bền bỉ phần lớn chọn xe Toyota.","body":[{"t":"Sức mua hồi phục sau bước giảm mạnh trong tháng 8 (thời điểm trùng với tháng 7 âm lịch) kết hợp sự xuất hiện của một số mẫu mã mới đồng thời đúng lúc , dầu \"leo thang\"… mang đến cơ hội tăng trưởng doanh số cho dòng ô tô hybrid - xe sử dụng hệ thống động cơ xăng kết hợp mô-tơ điện (gồm mild-hybrid, plug-in hybrid và hybrid). Tuy nhiên, xu hướng chọn mua ô tô hybrid của người Việt vẫn không có nhiều thay đổi khi phần lớn vẫn chuộng .","k":"p"},{"t":"Lượng tiêu thụ ô tô hybrid tại Việt Nam tăng 36% trong tháng 9.2026","k":"h"},{"t":"Theo số liệu bán hàng vừa được Hiệp hội Các nhà sản xuất ô tô Việt Nam (VAMA) công bố, trong tháng 9.2026, doanh số bán ô tô mới các loại của các thành viên thuộc VAMA đạt tổng cộng 35.094 xe ô tô các loại, tăng 38% so với tháng 8.2026. Như vậy, sau khi quay đầu sụt giảm trong tháng 8 - thời điểm trùng với tháng 7 âm lịch, thị trường ô tô lập tức lấy lại nhịp tăng trưởng. Trong bối cảnh đó, phân khúc cũng ghi nhận tín hiệu khởi sắc về mặt doanh số bán hàng.","k":"p"},{"t":"Theo VAMA, tổng lượng ô tô hybrid của các thành viên VAMA bán ra thị trường trong tháng 9 vừa qua đạt 2.168 xe, tăng 780 xe tương đương 36% so với tháng 8.2026. Đây là một trong những tháng bán hàng có kết quả tốt nhất của dòng tại Việt Nam tính từ đầu năm 2026 đến nay, chỉ xếp sau tháng 3 (đạt 3.143 xe) và tháng 6 (đạt 2.347 xe).","k":"p"},{"t":"Kết quả này thậm chí vẫn chưa phản ánh hết quy mô của tại Việt Nam do chưa bao gồm doanh số bán các phiên bản hybrid của một số mẫu xe do KIA phân phối tại Việt Nam như KIA Carnival HEV, Sportage HEV hay Sorento HEV… cũng như lượng xe hybrid của Hyundai, Mercedes-Benz hay các hãng xe Trung Quốc bán ra thị trường. Tuy nhiên cũng phần nào cho thấy nhu cầu hybrid của người Việt đang trên đà tăng trưởng.","k":"p"},{"t":"Tháng 9.2026, thị trường ô tô hybrid tại Việt Nam có thêm sự góp mặt của Toyota Land Cruiser HEV","k":"p"},{"t":"Ảnh: TOYOTA","k":"cap"},{"t":"Ngoài sự hồi phục của thị trường, việc một số phiên bản xe hybrid mới xuất hiện trên thị trường như đặt trong bối cảnh giá xăng, dầu liên tục \"leo thang\" trong thời gian gần đây đã thúc đẩy nhu cầu mua xe hybrid gia tăng. Với một số khách hàng vốn đề cao yếu tố tiết kiệm nhiện liệu nhưng vẫn e ngại chuyện sạc pin, giới hạn quãng đường di chuyển và không muốn thay đổi thói quen dùng ô tô… thì xe hybrid được xem là lựa chọn khả thi nhất.","k":"p"},{"t":"Ô tô hybrid của Toyota vẫn hút khách nhất","k":"h"},{"t":"Trong bối cảnh xe hybrid xuất hiện ngày càng nhiều nhưng độ bền bỉ vẫn cần thời gian để kiểm chứng, phần lớn người Việt đè cao yếu tố \"ăn chắc, mặc bền\" cũng như giá trị bán lại vẫn ưu tiên lựa chọn các mẫu mã ô tô hybrid thương hiệu Nhật Bản, đặc biệt là xe Toyota.","k":"p"},{"t":"Số liệu được PV Thanh Niên tổng hợp từ báo cáo bán hàng của VAMA cho thấy, trong số các thương hiệu ô tô thuộc VAMA cập nhật doanh số xe hybrid, Toyota lại tiếp tục dẫn đầu. Cụ thể, trong tháng 9.2026 Toyota đã bán ra thị trường Việt Nam 1.821 xe hybrid, tăng 775 xe, tương đương 42,6%.","k":"p"},{"t":"10 mẫu ô tô hybrid hút khách nhất Việt Nam tháng 9.2026 (Nguồn: VAMA)","k":"cap"},{"t":"Trong đó, Toyota Innova Cross HEV, Toyota Corolla Cross HEV là những phiên bản ô tô hybrid bán chạy nhất Việt Nam của hãng xe Nhật Bản trong tháng qua với doanh số đạt hơn 600 chiếc. Toyota cũng áp đảo danh sách khi có tới 4 mẫu xe góp mặt. Không chỉ tạo sức hút về thương hiệu, hãng xe Nhật Bản cũng đang từng bước đa dạng hoá danh mục sản phẩm xe hybrid tại Việt Nam. Với việc bổ sung thêm Toyota Land Cruiser HEV, Toyota hiện có tới 7 phiên bản xe hybrid trong danh mục sản phẩm, trải đều ở các phân khúc khác nhau.","k":"p"},{"t":"Honda chỉ bán được 234 xe hybrid trong tháng 9.2026, giảm 17 xe tương đương 7% với tháng 8.2026. Trong đó, mẫu CR-V e:HEV RS vẫn đóng vai trò \"đầu tàu\" với 189 xe được bàn giao đến tay khách hàng. Suzuki cũng chỉ đạt 113 xe, tăng 22 xe tương đương 19,5% so với tháng trước đó, đây cũng chính là kết quả bán hàng của mẫu XL7 Hybrid trong bối cảnh Fronx Hybrid không được hãng xe Nhật Bản công bố doanh số.","k":"p"},{"t":"Cộng dồn 9 tháng đã qua của năm 2026 đạt 16.057 xe, tăng 6.272 xe tương đương gần 39,1% so với cùng kỳ năm ngoái.","k":"p"}]}];
